Object.assign(window.TEM8_DICTIONARY, {"friendliness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving towards someone in a way that shows you like them and are ready to talk to them or help them","cn":""},{"en":"friendly and caring about other people, in a way that makes people like you and feel comfortable","cn":""}]},"examples":[{"en":"I’ve found a great pub – good beer and a friendly atmosphere.","cn":"","src":"ld"},{"en":"Why is he suddenly so friendly towards you, Charlotte?","cn":"","src":"ld"}],"media":{"uk":"media/uk/friendliness__gb_1.mp3","us":"media/us/friendliness__us_1.mp3"},"oxford":{"phon":"ˈfrendlinəs","pos":"noun","senses":[{"en":"kind pleasant behaviour towards somebody you like or want to help","cn":"友善：对您喜欢或想要帮助的人的一种愉快的举止","ex":{"en":"We were greeted with warmth and friendliness.","cn":"我们受到了热情和友好的欢迎。"}},{"en":"the fact of not treating somebody as an enemy","cn":"友好的；和睦的","ex":{"en":"the friendliness of its relations with the other villages","cn":"与其他村庄的友好关系"}},{"en":"the quality of being helpful and easy to use or of helping somebody/something or not harming them/it","cn":"友善：乐于助人且易于使用或帮助某人/某物或不伤害他们/它的品质","ex":{"en":"I was impressed by the friendliness of the website.","cn":"该网站的友好性给我留下了深刻的印象。"}}]}},"frustrated":{"media":{"uk":"media/uk/frustrated__gb_1.mp3","us":"media/us/frustrated__us_1.mp3"},"oxford":{"phon":"frʌˈstreɪtɪd","pos":"adjective","senses":[{"en":"feeling annoyed and impatient because you cannot do or achieve what you want","cn":"懊丧；懊恼；沮丧","ex":{"en":"It's very easy to get frustrated in this job.","cn":"这个工作很容易令人懊恼。"}},{"en":"having no effect; not being satisfied","cn":"无效的；没有得到满足的","ex":{"en":"He stamped his foot in frustrated rage.","cn":"他怒气难消，气得跺脚。"}},{"en":"unable to be successful in a particular career","cn":"失意的；不得志的","g":"[only before noun]","ex":{"en":"a frustrated artist","cn":"不得志的艺术家"}},{"en":"not satisfied sexually","cn":"性欲没有得到满足的"}]},"examples":[{"en":"It's very easy to get frustrated in this job.","cn":"这个工作很容易令人懊恼。"},{"en":"They felt frustrated at the lack of progress.","cn":"没有进展，他们感到懊丧。"}],"base":"frustrate"},"fragile":{"media":{"uk":"media/uk/fragile__gb_1.mp3","us":"media/us/fragile__us_1.mp3"},"oxford":{"phon":"ˈfrædʒaɪl","pos":"adjective","senses":[{"en":"easily broken or damaged","cn":"易碎的；易损的","ex":{"en":"fragile china/glass/bones","cn":"易碎的瓷器／玻璃制品／骨骼"}},{"en":"weak and uncertain; easy to destroy or harm","cn":"不牢固的；脆弱的","ex":{"en":"a fragile alliance/ceasefire/relationship","cn":"不牢固的联盟；不确定的停火／关系"}},{"en":"thin or light and often beautiful","cn":"纤巧的；精细的；纤巧美丽的","ex":{"en":"fragile beauty","cn":"纤美"}},{"en":"not strong and likely to become ill","cn":"虚弱的","lab":"British English, informal，，","ex":{"en":"Her father is now 86 and in fragile health.","cn":"她的父亲现在 86 岁，身体虚弱。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脆弱的;不确定的","en":"If you describe a situation as fragile, you mean that it is weak or uncertain, and unlikely to be able to resist strong pressure or attack.","ex":{"en":"The fragile economies of several southern African nations could be irreparably damaged","cn":"一些南非国家的脆弱经济可能会被彻底破坏，无法挽回。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易碎的;易坏的","en":"Something that is fragile is easily broken or damaged.","ex":{"en":"He leaned back in his fragile chair.","cn":"他仰靠在那把摇摇晃晃的椅子上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(外表)精致的，精巧的","en":"Something that is fragile is very delicate or fine in appearance.","ex":{"en":"The haircut emphasised her fragile beauty.","cn":"发型突出了她的精致之美。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"虚弱的;无力的","en":"If someone feels fragile, they feel weak, for example because they are ill or have drunk too much alcohol.","ex":{"en":"He felt irritated and strangely fragile, as if he were recovering from a severe bout of flu.","cn":"他感到恼火和莫名其妙的虚弱，仿佛经历了一场重感冒，正在康复。"}}]},"examples":[{"en":"( BrE ) ( informal ) I'm feeling a bit fragile after last night (= not well, perhaps because of drinking too much alcohol).","cn":"昨夜以后我觉得身子有点发虚（可能是纵酒所致）。"},{"en":"Her father is now 86 and in fragile health.","cn":"她的父亲现在 86 岁，身体虚弱。"}]},"from":{"media":{"uk":"media/uk/from__gb_1.mp3","us":"media/us/from__us_1.mp3"},"oxford":{"phon":"frəm","pos":"preposition","senses":[{"en":"used to show where somebody/something starts","cn":"（表示起始点）从…起，始于","ex":{"en":"She began to walk away from him.","cn":"她开始离他而去。"}},{"en":"used to show what the origin of somebody/something is","cn":"（表示来源）来自，源于，出自，从…来","ex":{"en":"I'm from Italy.","cn":"我是意大利人。"}},{"en":"used to show who sent or gave something/somebody","cn":"（表示由某人发出或给出）寄自，得自","ex":{"en":"a letter from my brother","cn":"我哥哥来的信"}},{"en":"used to show when something starts","cn":"（表示开始的时间）从…开始","ex":{"en":"We're open from 8 a.m. to 7 p.m. every day.","cn":"我们每天从早 8 点至晚 7 点营业。"}},{"en":"used to show how far apart two places are","cn":"（表示两地的距离）离","ex":{"en":"100 metres from the scene of the accident","cn":"离事故现场 100 米"}},{"en":"used to show somebody’s position or point of view","cn":"（表示位置或观点）从","ex":{"en":"You can see the island from here.","cn":"从这里可以看见那海岛。"}},{"en":"used to show the range of something","cn":"（表示幅度或范围）从…（到）","ex":{"en":"The temperature varies from 30 degrees to minus 20.","cn":"温度在 30 度至零下 20 度之间变化。"}},{"en":"used to show the state or form of something/somebody before a change","cn":"（表示改变前的状态或形式）从…（到）","ex":{"en":"Things have gone from bad to worse.","cn":"情况越来越糟。"}},{"en":"used when making or recognizing a difference between two people or things","cn":"（区别二者时用）与…（不同）","ex":{"en":"Is Portuguese very different from Spanish?","cn":"葡萄牙语与西班牙语区别很大吗？"}},{"en":"used to show the material that something is made of","cn":"（表示所用的原料）由…（制成）","ex":{"en":"Steel is made from iron.","cn":"钢是由铁炼成的。"}},{"en":"used to show that somebody/something is separated or removed","cn":"（表示分离或去除）","ex":{"en":"The party was ousted from power after eighteen years.","cn":"该党执政十八年后被赶下台。"}},{"en":"used to show that something is prevented","cn":"（表示防止）使免遭，使免受","ex":{"en":"She saved him from drowning.","cn":"她救了他一命，使他免遭淹死。"}},{"en":"used to show the reason for something","cn":"（表示原因）由于，因为","ex":{"en":"She felt sick from tiredness.","cn":"她累得浑身不对劲。"}},{"en":"used to show the reason for making a judgement","cn":"（表示进行判断的原因）根据，从…来看","ex":{"en":"You can tell a lot about a person from their handwriting.","cn":"根据一个人的笔迹可以了解很多有关他的情况。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"出自;得自","en":"If something comes from a particular person or thing, or if you get something from them, they give it to you or they are the source of it.","ex":{"en":"He appealed for information from anyone who saw the attackers.","cn":"他呼吁任何看见袭击者的人提供信息。"}},{"pos":"PREP 介词","cn":"来自;产自","en":"Someone who comes from a particular place lives in that place or originally lived there. Something that comes from a particular place was made in that place.","ex":{"en":"...an art dealer from Zurich","cn":"来自苏黎世的艺术品商人"}},{"pos":"PREP 介词","cn":"为…(工作);在…(工作)","en":"A person from a particular organization works for that organization.","ex":{"en":"...a representative from the Israeli embassy.","cn":"以色列大使馆的代表"}},{"pos":"PREP 介词","cn":"从…(离开或移开)","en":"If someone or something moves or is moved from a place, they leave it or are removed, so that they are no longer there.","ex":{"en":"The guests watched as she fled from the room.","cn":"客人们看着她逃离了房间。"}},{"pos":"PREP 介词","cn":"(取)自…;从…(分开)","en":"If you take one thing or person from another, you move that thing or person so that they are no longer with the other or attached to the other.","ex":{"en":"In many bone transplants, bone can be taken from other parts of the patient's body","cn":"在许多骨移植手术中，可以从病人身体的其他部位取骨。"}},{"pos":"PREP 介词","cn":"从…(减去或扣除)","en":"If you take something from an amount, you reduce the amount by that much.","ex":{"en":"The £103 is deducted from Mrs Adams' salary every month","cn":"这 103 英镑每月从亚当斯夫人的工资里扣掉。"}},{"pos":"PREP 介词","cn":"离开;不在","en":"From is used in expressions such as away from or absent from to say that someone or something is not present in a place where they are usually found.","ex":{"en":"Her husband worked away from home a lot","cn":"她丈夫经常离家在外工作。"}},{"pos":"PREP 介词","cn":"从…(回来)","en":"If you return from a place or an activity, you return after being in that place or doing that activity.","ex":{"en":"My son Colin has just returned from Amsterdam.","cn":"我儿子科林刚从阿姆斯特丹回来。"}},{"pos":"PREP 介词","cn":"(已经)从…(回来)","en":"If you are back from a place or activity, you have left it and have returned to your former place.","ex":{"en":"Our economics correspondent, James Morgan, is just back from Germany","cn":"我们的财经记者詹姆斯·摩根刚刚从德国回来。"}},{"pos":"PREP 介词","cn":"从…(看到或听到)","en":"If you see or hear something from a particular place, you are in that place when you see it or hear it.","ex":{"en":"Visitors see the painting from behind a plate glass window","cn":"参观者隔着平板玻璃橱窗欣赏那幅画。"}},{"pos":"PREP 介词","cn":"从…(挂下或伸出)","en":"If something hangs or sticks out from an object, it is attached to it or held by it.","ex":{"en":"Hanging from his right wrist is a heavy gold bracelet.","cn":"他的右腕上戴着一只沉甸甸的金手镯。"}},{"pos":"PREP 介词","cn":"(表示距离)离(某处)…","en":"You can use from when giving distances. For example, if a place is fifty miles from another place, the distance between the two places is fifty miles.","ex":{"en":"The centre of the town is 4 kilometres from the station","cn":"市中心距离车站 4 公里远。"}},{"pos":"PREP 介词","cn":"(交通线路)起自…，连接…","en":"If a road or railway line goes from one place to another, you can travel along it between the two places.","ex":{"en":"...the road from St Petersburg to Tallinn.","cn":"从圣彼得堡到塔林的路"}},{"pos":"PREP 介词","cn":"由…(制成)","en":"From is used, especially in the expression made from, to say what substance has been used to make something.","ex":{"en":"...bread made from white flour.","cn":"精白面粉做的面包"}},{"pos":"PREP 介词","cn":"(表示时间)从…起，始于","en":"You can use from when you are talking about the beginning of a period of time.","ex":{"en":"She studied painting from 1926 and also worked as a commercial artist","cn":"她从 1926 年起开始学画，同时还从事着商业艺术家的工作。"}},{"pos":"PREP 介词","cn":"(表示范围)从…到…，由…至…","en":"You say from one thing to another when you are stating the range of things that are possible, or when saying that the range of things includes everything in a certain category.","ex":{"en":"There are 94 countries represented in Barcelona, from Algeria to Zimbabwe","cn":"包括从阿尔及利亚到津巴布韦的 94 个国家在巴塞罗那设有代表处。"}},{"pos":"PREP 介词","cn":"(表示形式或状态)从…变成…","en":"If something changes from one thing to another, it stops being the first thing and becomes the second thing.","ex":{"en":"The expression on his face changed from sympathy to surprise","cn":"他脸上的表情从同情变为惊讶。"}},{"pos":"PREP 介词","cn":"因为;由于;出于","en":"You use from after some verbs and nouns when mentioning the cause of something.","ex":{"en":"The problem simply resulted from a difference of opinion","cn":"这个问题仅仅是由于意见分歧引起的。"}},{"pos":"PREP 介词","cn":"根据;依据","en":"You use from when you are giving the reason for an opinion.","ex":{"en":"She knew from experience that Dave was about to tell her the truth","cn":"经验告诉她戴夫就要对她说出实情了。"}},{"pos":"PREP 介词","cn":"(用于 protect, free, keep, prevent 等动词后)免于","en":"From is used after verbs with meanings such as 'protect', 'free', 'keep', and 'prevent' to introduce the action that does not happen, or that someone does not want to happen.","ex":{"en":"Such laws could protect the consumer from harmful or dangerous remedies","cn":"这样的法规可以保护消费者免受有害或者危险药品的威胁。"}}]},"examples":[{"en":"The temperature varies from 30 degrees to minus 20.","cn":"温度在 30 度至零下 20 度之间变化。"},{"en":"The store sells everything from shoelaces to computers.","cn":"这家商店出售的商品从鞋带到计算机应有尽有。"}]},"freely":{"media":{"uk":"media/uk/freely__gb_1.mp3","us":"media/us/freely__us_1.mp3"},"oxford":{"phon":"ˈfriːli","pos":"adverb","senses":[{"en":"without anyone trying to prevent or control something","cn":"不受限制地；无拘无束地；自由地","ex":{"en":"the country’s first freely elected president","cn":"该国第一次自由选举出的总统"}},{"en":"without anything stopping the movement or flow of something","cn":"无阻碍地；畅通地","lab":"figurative","ex":{"en":"When the gate is raised, the water can flow freely.","cn":"闸门提起时水就可以畅流。"}},{"en":"in an honest way without worrying about what people will say or do","cn":"直率地；坦率地","ex":{"en":"For the first time he was able to speak freely without the fear of reprisals against his family.","cn":"他第一次能够直言不讳而不怕家人遭到报复。"}},{"en":"without trying to avoid the truth even though it might be unpleasant or embarrassing","cn":"自愿地；心甘情愿地","ex":{"en":"I freely admit that I made a mistake.","cn":"我爽快地承认我犯了错误。"}},{"en":"in a willing and generous way","cn":"慷慨地；大方地","ex":{"en":"Millions of people gave freely in response to the appeal for the victims of the earthquake.","cn":"为响应救济地震灾民的呼吁，几百万人慷慨相助。"}},{"en":"a piece of writing that is translated freely is not translated exactly but the general meaning is given","cn":"以意译方法；不拘于原文"}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"经常地;大量地","en":"Freely means many times or in large quantities.","ex":{"en":"We have referred freely to his ideas","cn":"我们频繁地提到了他的观点。"}},{"pos":"ADV-GRADED 副词","cn":"坦率地;无顾忌地","en":"If you can talk freely, you can talk without needing to be careful about what you say.","ex":{"en":"She wondered whether he had someone to whom he could talk freely.","cn":"她不知道他是否有可以倾心交谈的对象。"}},{"pos":"ADV-GRADED 副词","cn":"自愿地;心甘情愿地","en":"If someone gives or does something freely, they give or do it willingly, without being ordered or forced to do it.","ex":{"en":"Danny shared his knowledge freely with anyone interested","cn":"丹尼十分乐意地和所有感兴趣的人分享他的知识。"}},{"pos":"ADV-GRADED 副词","cn":"无阻碍地;顺畅地","en":"If something or someone moves freely, they move easily and smoothly, without any obstacles or resistance.","ex":{"en":"The clay court was slippery and he was unable to move freely","cn":"红土网球场很滑，他不能自如地移动。"}}]},"examples":[{"en":"EU citizens can now travel freely between member states.","cn":"欧盟国家的公民现在可以在成员国之间自由旅行。"},{"en":"Millions of people gave freely in response to the appeal for the victims of the earthquake.","cn":"为响应救济地震灾民的呼吁，几百万人慷慨相助。"}]},"frosted":{"media":{"uk":"media/uk/frosted__gb_1.mp3","us":"media/us/frosted__us_1.mp3"},"oxford":{"phon":"ˈfrɒstɪd","pos":"adjective","senses":[{"en":"that has been given a rough surface, so that it is difficult to see through","cn":"毛面的；磨砂的","g":"[only before noun]"},{"en":"covered with frosting","cn":"覆有糖霜的","lab":"especially North American English"},{"en":"covered with frost","cn":"结霜的","ex":{"en":"the frosted garden","cn":"寒霜覆盖的花园"}},{"en":"containing very small shiny pieces","cn":"含有闪光小颗粒的","ex":{"en":"frosted eyeshadow","cn":"闪光点眼影"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(玻璃)磨砂的，毛面的","en":"Frosted glass is glass that you cannot see through clearly.","ex":{"en":"The top half of the door to his office was of frosted glass.","cn":"他办公室门的上半部分是磨砂玻璃。"}},{"pos":"ADJ 形容词","cn":"结霜的;被霜覆盖的","en":"Frosted means covered with frost.","ex":{"en":"...the frosted trees.","cn":"被霜覆盖的树木"}},{"pos":"ADJ 形容词","cn":"覆有霜状物的","en":"Frosted means covered with something that looks like frost.","ex":{"en":"...frosted blue eye shadow.","cn":"蓝色霜状眼影"}},{"pos":"ADJ 形容词","cn":"覆有糖霜的","en":"Frosted means covered with icing.","ex":{"en":"...a plate of frosted cupcakes.","cn":"一盘撒有糖霜的纸杯蛋糕"}}]},"examples":[{"en":"the frosted garden","cn":"寒霜覆盖的花园"},{"en":"frosted eyeshadow","cn":"闪光点眼影"}],"base":"frost"},"frank":{"media":{"uk":"media/uk/frank__gb_1.mp3","us":"media/us/frank__us_1.mp3"},"oxford":{"phon":"fræŋk","pos":"adjective","senses":[{"en":"honest and direct in what you say, sometimes in a way that other people might not like","cn":"坦率的；直率的","ex":{"en":"a full and frank discussion","cn":"坦诚而充分的讨论"}},{"en":"to stamp a mark on an envelope, etc. to show that the cost of posting it has been paid or does not need to be paid","cn":"（在信件上）盖邮资已付印记，盖免付邮资印记","pos":"verb"},{"en":"a first name for boys, sometimes short for Francis","cn":"弗兰克（男子名，有时为 Francis 缩写）","pos":""}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坦白的;直率的;坦诚的","en":"If someone is frank, they state or express things in an open and honest way.","ex":{"en":"'It is clear that my client has been less than frank with me,' said his lawyer","cn":"“很明显我的委托人对我不够坦白，”他的律师说。"}},{"pos":"VERB 动词","cn":"(在信封或邮包上)盖邮资已付戳记，盖免费邮戳","en":"When a letter or parcel is franked, it is marked with a symbol that shows that the proper charge has been paid or that no stamp is needed.","ex":{"en":"The letter was franked in London on August 6.","cn":"这封信 8 月 6 日在伦敦盖过免费邮戳。"}},{"pos":"PHRASE 短语","cn":"(尤用于观点可能令人不悦时)老实讲，坦白说","en":"You can say 'to be frank' or 'to be frank with you' to introduce a statement which is your honest opinion, especially when the person you are talking to might not like it.","ex":{"en":"To be frank, he could also be a bit of a bore","cn":"老实说，他有时也会让人厌烦。"}}]},"examples":[{"en":"To be frank with you, I think your son has little chance of passing the exam.","cn":"坦诚相告，我认为你的儿子不大可能通过考试。"},{"en":"He was very frank about his relationship with the actress.","cn":"他对自己和那位女演员的关系直言不讳。"}]},"friendly":{"media":{"uk":"media/uk/friendly__gb_1.mp3","us":"media/us/friendly__us_1.mp3"},"oxford":{"phon":"ˈfrendli","pos":"adjective","senses":[{"en":"behaving in a kind and pleasant way because you like somebody or want to help them","cn":"友爱的；友好的","ex":{"en":"a warm and friendly person","cn":"热情友好的人"}},{"en":"showing that somebody is kind; making you feel relaxed and as though you are among friends","cn":"善意的；亲切的；和蔼可亲的","ex":{"en":"a friendly smile/welcome","cn":"亲切的微笑；友好的欢迎"}},{"en":"treating somebody as a friend","cn":"朋友似的","ex":{"en":"We soon became friendly with the couple next door.","cn":"我们很快就和隔壁的夫妇友好相处了。"}},{"en":"not treating somebody/something as an enemy","cn":"友好的；和睦的","ex":{"en":"The government has maintained friendly relations with the Japanese.","cn":"政府与日本人保持友好关系。"}},{"en":"that is helpful and easy to use; that helps somebody/something or does not harm it","cn":"好用的；有用的；无害的","ex":{"en":"This software is much friendlier than the previous version.","cn":"这个软件比之前的版本好用得多。"}},{"en":"in which people are not arguing or competing in a serious or unpleasant way","cn":"非对抗性的；友好的","g":"[usually before noun]","ex":{"en":"a friendly argument","cn":"友好的辩论"}},{"en":"not part of an important competition","cn":"友谊的","g":"[only before noun]","lab":"British English","ex":{"en":"It was only a friendly match.","cn":"这仅是一场友谊赛。"}},{"en":"a game of football (soccer), rugby, etc. that is not part of an important competition","cn":"（足球、橄榄球等的）友谊赛","ex":{"en":"He played for England in a friendly against Spain.","cn":"他代表英格兰队参加了与西班牙队的友谊赛。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"友善的;友好的;好相处的","en":"If someone is friendly, they behave in a pleasant, kind way, and like to be with other people.","ex":{"en":"Godfrey had been friendly to me.","cn":"戈弗雷一度对我很友善。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"朋友(般)的;要好的","en":"If you are friendly with someone, you like each other and enjoy spending time together.","ex":{"en":"I'm friendly with his mother","cn":"我和他母亲很要好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"盟友的;友邦的","en":"You can describe another country or their government as friendly when they have good relations with your own country rather than being an enemy.","ex":{"en":"...a worsening in relations between the two previously friendly countries.","cn":"这两个曾经友好的国家之间关系的恶化"}},{"pos":"N-COUNT 可数名词","cn":"友谊赛","en":"In sport, a friendly is a match which is not part of a competition, and is played for entertainment or practice, often without any serious effort to win.","ex":{"en":"Athletic Bilbao agreed to play a friendly at Real Sociedad.","cn":"毕尔巴鄂竞技队同意在皇家社会队主场打一场友谊赛。"}}]},"examples":[{"en":"We soon became friendly with the couple next door.","cn":"我们很快就和隔壁的夫妇友好相处了。"},{"en":"She was on friendly terms with most of the hospital staff.","cn":"她和医院大多数工作人员关系融洽。"}]},"frost":{"media":{"uk":"media/uk/frost__gb_1.mp3","us":"media/us/frost__us_1.mp3"},"oxford":{"phon":"frɒst","pos":"noun","senses":[{"en":"a weather condition in which the temperature drops below 0° Celsius (= freezing point) so that a thin white layer of ice forms on the ground and other surfaces, especially at night","cn":"严寒天气；霜冻；冰点以下的温度","g":"[uncountable, countable]","ex":{"en":"It will be a clear night with some ground frost.","cn":"今夜晴，部分地面有霜冻。"}},{"en":"the thin white layer of ice that forms when the temperature drops below 0° Celsius","cn":"霜","g":"[uncountable]","ex":{"en":"The car windows were covered with frost.","cn":"车窗玻璃结了霜。"}},{"en":"to cover something or to become covered with a thin white layer of ice","cn":"（使）蒙上霜，结霜","g":"[transitive, intransitive]","ex":{"en":"The mirror was frosted up.","cn":"镜子蒙了一层霜。"},"pos":"verb"},{"en":"to cover a cake with frosting","cn":"给（糕饼）覆上糖霜","g":"[transitive]","lab":"especially North American English","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"霜;霜冻;严寒天气","en":"When there is frost or a frost, the temperature outside falls below freezing point and the ground becomes covered in ice crystals.","ex":{"en":"There is frost on the ground and snow is forecast","cn":"地上结霜了，而且预报说会有雪。"}},{"pos":"PHRASE 短语","cn":"冰点以下…度;零下…度","en":"When someone says that there are a particular number of degrees of frost they mean that the temperature is that number of degrees below freezing point.","ex":{"en":"We had 11 degrees of frost last night.","cn":"昨天夜里气温降到了零下 11 度。"}}]},"examples":[{"en":"It will be a clear night with some ground frost.","cn":"今夜晴，部分地面有霜冻。"},{"en":"There were ten degrees of frost (= the temperature dropped to -10°C) last night.","cn":"昨夜零下 10 摄氏度。"}]},"fretting":{"lemma":"fret"},"fragmentation":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to break something, or be broken into a lot of small separate parts – used to show disapproval","cn":""}]},"examples":[{"en":"the dangers of fragmenting the Health Service","cn":"","src":"ld"}],"media":{"uk":"media/uk/fragmentation__gb_1.mp3","us":"media/us/fragmentation__us_1.mp3"},"oxford":{"phon":"ˌfræɡmenˈteɪʃn","pos":"noun","senses":[{"en":"the act or process of breaking or making something break into small pieces or parts","cn":"（使）碎裂，破裂，分裂","ex":{"en":"the fragmentation of the country into small independent states","cn":"国家分裂成独立的小国"}}]}},"fruit":{"media":{"img":["media/pic/fruit_comp.jpg","media/thumb/apple.jpg"],"uk":"media/uk/fruit__gb_1.mp3","us":"media/us/fruit__us_1.mp3"},"oxford":{"phon":"fruːt","pos":"noun","senses":[{"en":"the part of a plant that consists of one or more seeds and a soft inner part, can be eaten as food and usually tastes sweet","cn":"水果","g":"[countable, uncountable]","ex":{"en":"tropical fruits, such as bananas and pineapples","cn":"热带水果，如香蕉和菠萝"}},{"en":"a part of a plant or tree that is formed after the flowers have died and in which seeds develop","cn":"果实","g":"[countable]","lab":"specialist","ex":{"en":"The crab apple bears a small, bitter fruit.","cn":"沙果树结的果子又小又涩。"}},{"en":"all the natural things that the earth produces","cn":"（大地的）产物；农产品","g":"[countable, usually plural]","lab":"literary"},{"en":"an offensive word for a gay man","cn":"基佬，“兔子”（对男同性恋者的蔑称）","g":"[countable]","lab":"taboo, offensive, slang，，，，"},{"en":"to produce fruit","cn":"结果","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"水果;果实","en":"Fruit or a fruit is something which grows on a tree or bush and which contains seeds or a stone covered by a substance that you can eat.","ex":{"en":"Fresh fruit and vegetables provide fibre and vitamins.","cn":"新鲜水果和蔬菜提供植物纤维素和维生素。"}},{"pos":"VERB 动词","cn":"结果实","en":"If a plant fruits, it produces fruit.","ex":{"en":"The scientists will study the variety of trees and observe which are fruiting.","cn":"科学家将研究各种树木，并观察哪些会结果实。"}},{"pos":"N-COUNT 可数名词","cn":"成果;硕果","en":"The fruits or the fruit of someone's work or activity are the good things that result from it.","ex":{"en":"The team have really worked hard and Mansell is enjoying the fruits of that labour","cn":"这支队伍真正付出了辛劳，而曼塞尔正在享受着这种辛劳的成果。"}},{"pos":"PHRASE 短语","cn":"取得成果;奏效;产生好的结果","en":"If the effort that you put into something or a particular way of doing something bears fruit, it is successful and produces good results.","ex":{"en":"Eleanor's work among the women will, I trust, bear fruit","cn":"我相信埃莉诺在妇女中所做的工作会见成效的。"}},{"pos":"PHRASE 短语","cn":"(项目或活动的)初步成果，最初成效","en":"The first fruits or the first fruit of a project or activity are its earliest results or profits.","ex":{"en":"This project is one of the first fruits of commercial co-operation between the two countries.","cn":"这个项目是两国商业合作的初步成果之一。"}}]},"examples":[{"en":"The book is the fruit of years of research.","cn":"这本书是多年研究的成果。"},{"en":"tropical fruits, such as bananas and pineapples","cn":"热带水果，如香蕉和菠萝"}]},"frontier":{"media":{"uk":"media/uk/frontier__gb_1.mp3","us":"media/us/frontier__us_1.mp3"},"oxford":{"phon":"ˈfrʌntɪə(r)","pos":"noun","senses":[{"en":"a line that separates two countries, etc.; the land near this line","cn":"国界；边界；边境","g":"[countable]","lab":"British English","ex":{"en":"the frontier between the land of the Saxons and that of the Danes","cn":"撒克逊人土地和丹麦人土地的边界"}},{"en":"the edge of land where people have settled and built towns, beyond which the country is wild and unknown, especially in the western US in the 19th century","cn":"（尤指 19 世纪美国西部的）开发地区边缘地带，边远地区","g":"[singular]","ex":{"en":"a remote frontier settlement","cn":"边远地区定居点"}},{"en":"the limit of something, especially the limit of what is known about a particular subject or activity","cn":"（学科或活动的）界限，边缘","g":"[countable, usually plural]","ex":{"en":"to push back the frontiers of science (= to increase knowledge of science)","cn":"开拓科学新领域"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"边界;边境","en":"A frontier is a border between two countries.","ex":{"en":"It wasn't difficult then to cross the frontier.","cn":"那时穿越边境并不困难。"}},{"pos":"N-COUNT 可数名词","cn":"西部边疆,边远地区(指 20 世纪前美国西部欧洲移民尚未定居的部分)","en":"When you are talking about the western part of America before the twentieth century, you use frontier to refer to the area beyond the part settled by Europeans.","ex":{"en":"...a far-flung outpost on the frontier.","cn":"远驻西部边疆的前哨"}},{"pos":"N-COUNT 可数名词","cn":"(尤指知识的)前沿，尖端，新领域","en":"The frontiers of something, especially knowledge, are the limits to which it extends.","ex":{"en":"...pushing back the frontiers of science.","cn":"推进科学前沿"}}]},"examples":[{"en":"the frontier between the land of the Saxons and that of the Danes","cn":"撒克逊人土地和古斯堪的纳维亚人土地的边界"},{"en":"a customs post on the frontier with Italy","cn":"与意大利交界的边境上的海关关卡"}]},"freight":{"media":{"uk":"media/uk/freight__gb_1.mp3","us":"media/us/freight__us_1.mp3"},"oxford":{"phon":"freɪt","pos":"noun","senses":[{"en":"goods that are transported by ships, planes, trains or lorries; the system of transporting goods in this way","cn":"（海运、空运或陆运的）货物；货运","ex":{"en":"to send goods by air freight","cn":"空运货物"}},{"en":"to send or carry goods by air, sea or train","cn":"寄送，运送（货物）；货运","pos":"verb"},{"en":"to fill something with a particular mood or tone","cn":"使充满（某种心情或口气）","g":"[usually passive]","lab":"literary","ex":{"en":"Each word was freighted with anger.","cn":"字字充满愤怒。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"货运","en":"Freight is the movement of goods by lorries, trains, ships, or aeroplanes.","ex":{"en":"France derives 16% of revenue from air freight.","cn":"法国 16%的岁入来自航空货运。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(货运)货物","en":"Freight is goods that are transported by lorries, trains, ships, or aeroplanes.","ex":{"en":"...26 tons of freight","cn":"26 吨货物"}},{"pos":"VERB 动词","cn":"以货运运输","en":"When goods are freighted, they are transported in large quantities over a long distance.","ex":{"en":"From these ports the grain is freighted down to Addis Ababa.","cn":"粮食从这些港口运到亚的斯亚贝巴。"}}]},"examples":[{"en":"Each word was freighted with anger.","cn":"字字充满愤怒。"},{"en":"to send goods by air freight","cn":"空运货物"}]},"fr":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"Father (used in front of the name of some Christian priests)","cn":"神父（用于姓名前）","ex":{"en":"Fr (Paul) O’Connor","cn":"（保罗·）奥康纳神父"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Fr is a written abbreviation for (书面缩略=)French or franc."},{"pos":"","cn":"神父(用于天主教牧师姓名前)","en":"Fr is a written abbreviation for (书面缩略=) Father when it is used in titles before the name of a Catholic priest."}]},"media":{"us":"media/ldoce/hwd/ame/a/fr_che.mp3"},"examples":[{"en":"Fr (Paul) O'Connor （","cn":"保禄）奥康纳神父"}]},"frequency":{"oxford":{"phon":"ˈfriːkwənsi","pos":"noun","senses":[{"en":"the rate at which something happens or is repeated","cn":"发生率；出现率；重复率","g":"[uncountable, countable]","ex":{"en":"Fatal road accidents have decreased in frequency over recent years.","cn":"近年来致命交通事故发生率已经下降。"}},{"en":"the fact of something happening often","cn":"频繁","g":"[uncountable]","ex":{"en":"the alarming frequency of computer errors","cn":"计算机出错的情况惊人的多"}},{"en":"the rate at which a sound or electromagnetic wave vibrates (= moves up and down)","cn":"（声波或电磁波振动的）频率","g":"[countable, uncountable]","lab":"specialist","ex":{"en":"a high/low frequency","cn":"高频；低频"}},{"en":"the number of radio waves for every second of a radio signal","cn":"频率（无线电信号每秒电波数）","g":"[countable, uncountable]","lab":"specialist","ex":{"en":"a frequency band","cn":"频带"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"频率;发生次数","en":"The frequency of an event is the number of times it happens during a particular period.","ex":{"en":"The frequency of Kara's phone calls increased rapidly","cn":"卡拉的电话飞速增多。"}},{"pos":"N-VAR 可变名词","cn":"(声波或无线电波的)频率，周率","en":"In physics, the frequency of a sound wave or a radio wave is the number of times it vibrates within a specified period of time.","ex":{"en":"You can't hear waves of such a high frequency.","cn":"如此高频率的声波是无法听到的。"}}]},"media":{"uk":"media/uk/frequency__gb_1.mp3","us":"media/us/frequency__us_1.mp3"},"examples":[{"en":"Objects like this turn up at sales with surprising frequency.","cn":"这样的东西在拍卖会上出人意料地频繁出现。"},{"en":"Fatal road accidents have decreased in frequency over recent years.","cn":"近年来致命交通事故发生率已经下降。"}]},"frequent":{"media":{"uk":"media/uk/frequent__gb_1.mp3","us":"media/us/frequent__us_1.mp3"},"oxford":{"phon":"ˈfriːkwənt","pos":"adjective","senses":[{"en":"happening or doing something often","cn":"频繁的；经常发生的","ex":{"en":"He is a frequent visitor to this country.","cn":"他常常访问这个国家。"}},{"en":"to visit a particular place often","cn":"常去，常到（某处）","ex":{"en":"We met in a local bar much frequented by students.","cn":"我们在学生经常去的一家酒吧里相遇。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"经常性的;频繁的","en":"If something is frequent, it happens often.","ex":{"en":"Bordeaux is on the main Paris-Madrid line so there are frequent trains","cn":"波尔多位于巴黎到马德里的铁路主干线上，来往列车频繁。"}},{"pos":"VERB 动词","cn":"常到;常去;常出入于","en":"If someone frequents a particular place, they regularly go there.","ex":{"en":"I hear he frequents the Cajun restaurant in Hampstead.","cn":"我听说他经常光顾汉普斯特德的卡津餐厅。"}}]},"examples":[{"en":"We met in a local bar much frequented by students.","cn":"我们在学生经常去的一家酒吧里相遇。"},{"en":"There is a frequent bus service into the centre of town.","cn":"公共汽车有很多班次开往市中心区。"}]},"freshwater":{"media":{"uk":"media/uk/freshwater__gb_1.mp3","us":"media/us/freshwater__us_1.mp3"},"oxford":{"phon":"ˈfreʃwɔːtə(r)","pos":"adjective","senses":[{"en":"living in water that is not the sea and does not contain salt","cn":"淡水中生长的","ex":{"en":"freshwater fish","cn":"淡水鱼"}},{"en":"having water that does not contain salt","cn":"淡水的","ex":{"en":"freshwater lakes","cn":"淡水湖"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(湖)淡水的;(生物)淡水中生长的","en":"A freshwater lake contains water that is not salty, usually in contrast to the sea. Freshwater creatures live in water that is not salty.","ex":{"en":"...Lake Balaton, the largest freshwater lake in Europe","cn":"巴拉顿湖，欧洲最大的淡水湖"}}]},"examples":[{"en":"freshwater fish","cn":"淡水鱼"},{"en":"freshwater lakes","cn":"淡水湖"}]},"fried":{"lemma":"fry","media":{"uk":"media/uk/fried__gb_1.mp3","us":"media/us/fried__us_1.mp3"}},"freshness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"completely new","cn":""},{"en":"made, produced etc a short time ago","cn":""}]},"examples":[{"en":"I’ll just make some fresh coffee.","cn":"","src":"ld"},{"en":"The report provides fresh evidence about the way the business was run.","cn":"","src":"ld"}],"media":{"uk":"media/uk/freshness__gb_1.mp3","us":"media/us/freshness__us_1.mp3"},"oxford":{"phon":"ˈfreʃnəs","pos":"noun","senses":[{"en":"the fact of food being recently produced or picked and not frozen, dried or preserved in tins or cans","cn":"新鲜的；新产的；刚摘的","g":"[uncountable]","ex":{"en":"We guarantee the freshness of all our produce.","cn":"我们保证我们的农产品都是新鲜的。"}},{"en":"the fact of being made or experienced recently","cn":"新近的；新近出现的；新近体验的","g":"[uncountable]","ex":{"en":"Based on the freshness of the tyre tracks, they were only one or two hours' drive ahead of us.","cn":"根据轮胎痕迹的新鲜程度，他们距离我们只有一两个小时的车程。"}},{"en":"the quality of being new or different","cn":"新鲜度：新鲜或与众不同的品质","g":"[uncountable, singular]","ex":{"en":"I like the freshness of his approach to the problem.","cn":"我喜欢他对这个问题新颖的处理方法。"}},{"en":"the quality of being pleasantly clean, pure or cool","cn":"清新的；凉爽的","g":"[uncountable, singular]","ex":{"en":"the cool freshness of the water","cn":"水的清凉"}},{"en":"the quality of being clear, bright and attractive","cn":"洁净的；明净的；亮丽的","g":"[uncountable, singular]","ex":{"en":"the crisp freshness of the colour in his paintings","cn":"他画作中色彩的清新"}}]}},"frantically":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done very quickly because you are in a hurry","cn":""},{"en":"a quick look, meal, visit, decision etc is done very quickly, because you do not have much time","cn":""}]},"examples":[{"en":"There was still no news of Jill, and her parents were getting frantic.","cn":"","src":"ld"},{"en":"Your mother’s been frantic with worry wondering where you’ve been.","cn":"","src":"ld"}],"media":{"uk":"media/uk/frantically__gb_1.mp3","us":"media/us/frantically__us_1.mp3"},"oxford":{"phon":"ˈfræntɪkli","pos":"adverb","senses":[{"en":"quickly and with a lot of activity, but in a way that is not very well organized","cn":"紧张忙乱的；手忙脚乱的","ex":{"en":"They worked frantically to finish on time.","cn":"他们拼命工作，以求按时完成。"}},{"en":"without controlling your emotions because you are extremely frightened or worried about something","cn":"（由于恐惧或担心）无法控制感情的，发狂似的","ex":{"en":"‘What do I do now?’ she thought frantically.","cn":"“我现在该怎么办？”她疯狂地想。"}}]}},"fraternity":{"media":{"uk":"media/uk/fraternity__gb_1.mp3","us":"media/us/fraternity__us_1.mp3"},"oxford":{"phon":"frəˈtɜːnəti","pos":"noun","senses":[{"en":"a group of people sharing the same profession, interests or beliefs","cn":"（有相同职业、爱好或信仰的）群体，同人；同好","g":"[countable + singular or plural verb]","ex":{"en":"members of the medical/banking/racing, etc. fraternity","cn":"医务界、银行界、赛马圈等同人"}},{"en":"a club for a group of male students at an American college or university","cn":"（美国男大学生的）联谊会，兄弟会","g":"[countable]","lab":"also North American English, informal，，"},{"en":"a feeling of friendship and support that exists between the members of a group","cn":"（团体内的）情谊，兄弟般的友谊，博爱","g":"[uncountable]","lab":"formal","ex":{"en":"the ideals of liberty, equality and fraternity","cn":"自由、平等和博爱的理想"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"兄弟情谊;友爱;互助","en":"Fraternity refers to friendship and support between people who feel they are closely linked to each other.","ex":{"en":"Bob needs the fraternity of others who share his mission.","cn":"鲍勃需要与他共同肩负这项使命的其他人的友爱互助。"}},{"pos":"N-COUNT 可数名词","cn":"同业者;具有相同职业(或兴趣)的人","en":"You can refer to people who have the same profession or the same interests as a particular fraternity .","ex":{"en":"...the spread of stolen guns among the criminal fraternity.","cn":"盗窃枪支流入犯罪团伙手中"}},{"pos":"N-COUNT 可数名词","cn":"(美国男大学生)联谊会，兄弟会","en":"In the United States, a fraternity is a society of male university or college students."}]},"examples":[{"en":"members of the medical/banking/racing, etc. fraternity","cn":"医务界、银行界、赛马圈等同仁"},{"en":"the ideals of liberty, equality and fraternity","cn":"自由、平等和博爱的理想"}]},"frenetic":{"media":{"uk":"media/uk/frenetic__gb_1.mp3","us":"media/us/frenetic__us_1.mp3"},"oxford":{"phon":"frəˈnetɪk","pos":"adjective","senses":[{"en":"involving a lot of energy and activity in a way that is not organized","cn":"发狂似的；狂乱的","ex":{"en":"a scene of frenetic activity","cn":"疯狂活动的场面"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"发狂似的;狂热的","en":"If you describe an activity as frenetic, you mean that it is fast and energetic, but rather uncontrolled.","ex":{"en":"...the frenetic pace of life in New York","cn":"纽约疯狂的生活节奏"}}]},"examples":[{"en":"a scene of frenetic activity","cn":"疯狂活动的场面"},{"en":"She rushes from job to job at a frenetic pace.","cn":"她发疯似的不停地跳槽。"}]},"friendship":{"oxford":{"phon":"ˈfrendʃɪp","pos":"noun","senses":[{"en":"a relationship between friends","cn":"友谊；朋友关系","g":"[countable]","ex":{"en":"They formed a close friendship at college.","cn":"他们在大学里结下了深厚的友谊。"}},{"en":"the feeling or relationship that friends have; the state of being friends","cn":"友情；友谊；友好","g":"[uncountable]","ex":{"en":"Your friendship is very important to me.","cn":"你的友情对我非常重要。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(相互之间的)友谊，友情，朋友关系","en":"A friendship is a relationship between two or more friends.","ex":{"en":"Giving advice when it's not called for is the quickest way to end a good friendship","cn":"在别人不需要的时候提供建议是葬送好友关系的最快方式。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(泛指的)友谊，友情，朋友情义","en":"You use friendship to refer in a general way to the state of being friends, or the feelings that friends have for each other.","ex":{"en":"...a hobby which led to a whole new world of friendship and adventure.","cn":"打开了一片充满友谊和冒险的全新天地的爱好"}},{"pos":"N-SING 单数名词","cn":"(某人的)友谊，友情","en":"If you have someone's friendship, they are your friend.","ex":{"en":"He had the friendship of Terry Jones and the respect of John Cleese","cn":"他得到了特里·琼斯的友谊和约翰·克利斯的尊敬。"}},{"pos":"N-VAR 可变名词","cn":"(两国之间的)友好关系，亲善","en":"Friendship is a relationship between two countries in which they help and support each other.","ex":{"en":"The President set the targets for the future to promote friendship with East Europe","cn":"总统确定了在未来加强同东欧的互助的目标。"}}]},"media":{"uk":"media/uk/friendship__gb_1.mp3","us":"media/us/friendship__us_1.mp3"},"examples":[{"en":"It's the story of an extraordinary friendship between a boy and a seal.","cn":"这是一个关于男孩和海豹之间非凡友谊的故事。"},{"en":"He seemed to have already struck up (= begun) a friendship with Jo.","cn":"他似乎已经开始和乔交朋友了。"}]},"frame":{"media":{"img":["media/ldoce/img/frame.jpg","media/pic/frame_comp.jpg"],"uk":"media/uk/frame__gb_1.mp3","us":"media/us/frame__us_1.mp3"},"oxford":{"phon":"freɪm","pos":"noun","senses":[{"en":"a strong border or structure of wood, metal, etc. that holds a picture, door, piece of glass, etc. in position","cn":"（图画、门、玻璃等的）框架","g":"[countable]","sc":"border","ex":{"en":"a picture/photo frame","cn":"画框；相框"}},{"en":"the supporting structure of a piece of furniture, a building, a vehicle, etc. that gives it its shape","cn":"（家具、建筑物、车辆等的）构架，支架，骨架","g":"[countable]","sc":"structure","ex":{"en":"a bicycle frame","cn":"自行车车架"}},{"en":"a structure of plastic or metal that holds the lenses in a pair of glasses","cn":"眼镜框","g":"[countable, usually plural]","sc":"of glasses","ex":{"en":"gold-rimmed frames","cn":"金边眼镜框"}},{"en":"the form or structure of a person or animal’s body","cn":"体形；身材；骨架","g":"[countable, usually singular]","sc":"person/animal’s body","ex":{"en":"to have a small/slender/large frame","cn":"小的／苗条的／大的体形"}},{"en":"the general ideas or structure that form the background to something","cn":"（构成某事物背景的）总的思想，体系，体制，模式","g":"[singular]","sc":"general ideas","ex":{"en":"In this course we hope to look at literature in the frame of its social and historical context.","cn":"在本课程中，我们希望从社会和历史背景的整体结构来看文学。"}},{"en":"one of the single photographs that a film or video is made of","cn":"帧头；画格；画面","g":"[countable]","sc":"of film"},{"en":"a single picture in a comic strip","cn":"（连环漫画中的）一幅画","g":"[countable]","sc":"of picture story"},{"en":"one of the separate areas on an internet page that you can scroll through (= read by moving the text up or down)","cn":"帧；页帧（框）；图文框","g":"[countable]","sc":"computing"},{"en":"a small wooden or metal frame covered with glass that you grow seeds or small plants in to protect them from cold weather","cn":"冷床，阳畦（用于保护育种或幼苗抗寒）","g":"[countable]","sc":"in garden"},{"en":"a single section of play in the game of snooker, etc., or in bowling","cn":"一轮；一回；一局","g":"[countable]","sc":"in snooker/bowling","ex":{"en":"He won the first frame easily.","cn":"他轻松赢得了第一局。"}},{"en":"to put or make a frame or border around something","cn":"给…做框；给…镶边","g":"[usually passive]","sc":"make border","ex":{"en":"The photograph had been framed.","cn":"照片已镶了框。"},"pos":"verb"},{"en":"to surround something/somebody in a way that makes an attractive image","cn":"衬托；映衬","sc":"make border","ex":{"en":"I like the way your hair frames your face.","cn":"我喜欢你的头发衬托你的脸的方式。"},"pos":"verb"},{"en":"to produce false evidence against an innocent person so that people think they are guilty","cn":"作伪证陷害","g":"[usually passive]","sc":"produce false evidence","ex":{"en":"He says he was framed.","cn":"他说他是被诬陷的。"},"pos":"verb"},{"en":"to create and develop something such as a plan, a system or a set of rules","cn":"制订；拟订","lab":"formal","sc":"develop plan/system","ex":{"en":"Measures to secure oil production must be framed in the context of rising energy demands.","cn":"确保石油生产的措施必须在能源需求不断增长的背景下制定。"},"pos":"verb"},{"en":"to express something in a particular way","cn":"（以某种方式）表达","sc":"express something","ex":{"en":"You'll have to be careful how you frame the question.","cn":"如何提出这个问题，你得慎重。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指挂在墙上展示的)画框，镜框","en":"The frame of a picture or mirror is the wood, metal, or plastic that is fitted around it, especially when it is displayed or hung on a wall.","ex":{"en":"Estelle kept a photograph of her mother in a silver frame on the kitchen mantelpiece.","cn":"埃丝特尔把母亲的一张镶银框的照片挂在厨房壁炉台上。"}},{"pos":"N-COUNT 可数名词","cn":"框;架;骨架;框架","en":"The frame of an object such as a building, chair, or window is the arrangement of wooden, metal, or plastic bars between which other material is fitted, and which give the object its strength and shape.","ex":{"en":"He supplied housebuilders with modern timber frames","cn":"他给房屋建筑商提供了现代的木构架。"}},{"pos":"N-COUNT 可数名词","cn":"眼镜框;眼镜架","en":"The frames of a pair of glasses are all the metal or plastic parts of it, but not the lenses.","ex":{"en":"He was wearing new spectacles with gold wire frames.","cn":"他戴了一副新的金边眼镜。"}},{"pos":"N-COUNT 可数名词","cn":"(人体的)骨架;(尤指)体形，体态","en":"You can refer to someone's body as their frame, especially when you are describing the general shape of their body.","ex":{"en":"Their belts are pulled tight against their bony frames.","cn":"他们的腰带紧紧裹着瘦骨嶙峋的身体。"}},{"pos":"N-COUNT 可数名词","cn":"(电影的)画面，镜头","en":"A frame of cinema film is one of the many separate photographs that it consists of.","ex":{"en":"Standard 8mm projects at 16 frames per second.","cn":"标准的 8 毫米的胶片每秒放映16 组镜头。"}},{"pos":"ADJ 形容词","cn":"(建筑)木制的，木结构的","en":"A frame building is one in which pieces of wood form the most important part of the structure, rather than bricks or stone.","ex":{"en":"He lives in a white-painted frame house behind a picket fence up in Connecticut.","cn":"他住在康涅狄格州北部一个漆成白色的木制房子里，屋子前面竖着尖桩篱栅。"}},{"pos":"VERB 动词","cn":"给…加框","en":"When a picture or photograph is framed, it is put in a frame.","ex":{"en":"The picture is now ready to be mounted and framed","cn":"这幅画现在可以装裱加框了。"}},{"pos":"VERB 动词","cn":"给…镶边;给…做框","en":"If an object is framed by a particular thing, it is surrounded by that thing in a way that makes the object more striking or attractive to look at.","ex":{"en":"The swimming pool is framed by tropical gardens","cn":"泳池周围都是栽种热带花卉的花园。"}},{"pos":"VERB 动词","cn":"创设，拟定，制定(规则、计划或体系)","en":"If someone frames something such as a set of rules, a plan, or a system, they create and develop it.","ex":{"en":"After the war, a convention was set up to frame a constitution.","cn":"战后，为制定宪法组织了一次会议。"}},{"pos":"VERB 动词","cn":"表达;表示","en":"If someone frames something in a particular style or kind of language, they express it in that way.","ex":{"en":"The story is framed in a format that is part thriller, part love story","cn":"情节的展开模式既像惊险小说，又像爱情故事。"}},{"pos":"VERB 动词","cn":"作伪证;陷害;诬陷","en":"If someone frames an innocent person, they make other people think that that person is guilty of a crime, by lying or inventing evidence.","ex":{"en":"I need to find out who tried to frame me","cn":"我得找出是谁企图诬陷我。"}},{"pos":"PHRASE 短语","cn":"在…考虑范围内;有机会成为…","en":"If someone is in the frame for something such as a job or position, they are being considered for it.","ex":{"en":"We need a win to keep us in the frame for the title.","cn":"要想保住夺冠希望，我们还需要再赢一场比赛。"}}]},"examples":[{"en":"In this course we hope to look at literature in the frame of its social and historical context.","cn":"在本课程中，我们希望从社会和历史背景的整体结构来看文学。"},{"en":"He stood there, head back, framed against the blue sky.","cn":"他站在那里，头向后仰，衬托在蓝天下。"}]},"fretwork":{"media":{"uk":"media/uk/fretwork__gb_1.mp3","us":"media/us/fretwork__us_1.mp3"},"oxford":{"phon":"ˈfretwɜːk","pos":"noun","senses":[{"en":"patterns cut into wood, metal, etc. to decorate it; the process of making these patterns","cn":"回纹饰；回纹饰工序"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"回纹细工;装饰浮雕(或透雕)细工","en":"Fretwork is wood or metal that has been decorated by cutting bits of it out to make a pattern."}]}},"frequently":{"media":{"uk":"media/uk/frequently__gb_1.mp3","us":"media/us/frequently__us_1.mp3"},"oxford":{"phon":"ˈfriːkwəntli","pos":"adverb","senses":[{"en":"often","cn":"频繁地；经常","ex":{"en":"Buses run frequently between the city and the airport.","cn":"公共汽车频繁地来往于市区与机场之间。"}}]},"examples":[{"en":"Buses run frequently between the city and the airport.","cn":"公共汽车频繁地来往于市区与机场之间。"},{"en":"some of the most frequently asked questions about the Internet","cn":"有关互联网的最常见的提问"}]},"frugality":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"spending money carefully and cleverly so that nothing is wasted and you can manage with the money you have","cn":""},{"en":"spending money only on things that are necessary or cheap because you want your money to last as long as possible","cn":""}]},"examples":[{"en":"As children we were taught to be frugal and hard-working.","cn":"","src":"ld"},{"en":"He led a remarkably frugal existence.","cn":"","src":"ld"}],"media":{"uk":"media/uk/frugality__gb_1.mp3","us":"media/us/frugality__us_1.mp3"},"oxford":{"phon":"fruːˈɡæləti","pos":"noun","senses":[{"en":"a way of living in which you use only as much money or food as is necessary","cn":"（对金钱、食物等）节约的，节俭的","ex":{"en":"She taught me simplicity and frugality.","cn":"她教会了我简单和节俭。"}},{"en":"the fact of a meal being small and plain and not costing very much","cn":"简单廉价的","ex":{"en":"the frugality of the meal","cn":"饮食节俭"}}]}},"frostbite":{"media":{"uk":"media/uk/frostbite__gb_1.mp3","us":"media/us/frostbite__us_1.mp3"},"oxford":{"phon":"ˈfrɒstbaɪt","pos":"noun","senses":[{"en":"a medical condition in which parts of the body, especially the fingers and toes, become damaged as a result of extremely cold temperatures","cn":"冻伤；冻疮","ex":{"en":"The climbers were all suffering from frostbite.","cn":"登山者都被冻伤了。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"冻疮;冻伤","en":"Frostbite is a condition in which parts of your body, such as your fingers or toes, become seriously damaged as a result of being very cold.","ex":{"en":"The survivors suffered from frostbite.","cn":"生还者身上有冻伤。"}}]},"examples":[{"en":"I nearly got frostbite .","cn":"我险些冻伤。"}]},"friendships":{"lemma":"friendship"},"frozen":{"media":{"uk":"media/uk/frozen__gb_2.mp3","us":"media/us/frozen__us_2.mp3"},"oxford":{"phon":"ˈfrəʊzn","pos":"adjective","senses":[{"en":"kept at a very low temperature in order to preserve it","cn":"冷冻的；冷藏的","g":"[usually before noun]","ex":{"en":"frozen peas/fish/pizza","cn":"冷冻的豌豆／鱼／比萨饼"}},{"en":"extremely cold","cn":"冻僵；极冷","g":"[not usually before noun]","ex":{"en":"I'm absolutely frozen!","cn":"我简直冻僵了！"}},{"en":"with a layer of ice on the surface","cn":"冰封的；封冻的；结冰的","ex":{"en":"There were skaters on the frozen river.","cn":"结冰的河面上有滑冰的人。"}},{"en":"covered with ice; so cold that it has become very hard","cn":"结冰的；冻硬的","ex":{"en":"The ground was frozen solid.","cn":"地面冻得硬邦邦的。"}},{"en":"unable to move because of a strong emotion such as fear or horror","cn":"吓呆；惊呆","ex":{"en":"She stared at him, frozen with shock.","cn":"她惊呆了，直瞪着他。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Frozen is the past participle of freeze."},{"pos":"ADJ 形容词","cn":"(地面)冰冻的，冻硬的","en":"If the ground is frozen it has become very hard because the weather is very cold.","ex":{"en":"It was bitterly cold now and the ground was frozen hard.","cn":"现在天气冷极了，地面都冻硬了。"}},{"pos":"ADJ 形容词","cn":"(食物)冷冻的","en":"Frozen food has been preserved by being kept at a very low temperature.","ex":{"en":"Frozen fish is a very healthy convenience food.","cn":"冻鱼是非常健康的方便食品。"}},{"pos":"ADJ 形容词","cn":"(人或身体某部位)冻坏的，冻僵的","en":"If you say that you are frozen, or a part of your body is frozen, you are emphasizing that you feel very cold.","ex":{"en":"He put one hand up to his frozen face","cn":"他用一只手捂在冰冷的脸上。"}},{"pos":"ADJ 形容词","cn":"(因非常担心、害怕等而)呆若木鸡的，一动不动的","en":"If you describe someone as frozen, you mean that their body is fixed in a particular position, for example because they are very worried or afraid.","ex":{"en":"One boy, aged about 11, looks frozen with fright","cn":"一个大约 11 岁的男孩吓得一动不动。"}}]},"examples":[{"en":"She stared at him, frozen with shock.","cn":"她惊呆了，直瞪着他。"},{"en":"The ground was frozen solid.","cn":"地面冻得硬邦邦的。"}],"base":"freeze"},"frustrate":{"oxford":{"phon":"frʌˈstreɪt","pos":"verb","senses":[{"en":"to make somebody feel annoyed or impatient because they cannot do or achieve what they want","cn":"使懊丧；使懊恼；使沮丧","ex":{"en":"What frustrates him is that there's too little money to spend on the project.","cn":"使他懊恼的是可用于这个项目的资金太少。"}},{"en":"to prevent somebody from doing something; to prevent something from happening or succeeding","cn":"阻止；防止；挫败","ex":{"en":"The rescue attempt was frustrated by bad weather.","cn":"营救行动因天气恶劣受阻。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使灰心;使沮丧;使愤怒","en":"If something frustrates you, it upsets or angers you because you are unable to do anything about the problems it creates.","ex":{"en":"These questions frustrated me","cn":"这些问题让我沮丧。"}},{"pos":"VERB 动词","cn":"挫败;阻挠…的成功","en":"If someone or something frustrates a plan or attempt to do something, they prevent it from succeeding.","ex":{"en":"The government has deliberately frustrated his efforts to gain work permits for his foreign staff.","cn":"政府故意阻挠他为自己的外籍员工申请工作许可证的努力。"}}]},"media":{"uk":"media/uk/frustrate__gb_1.mp3","us":"media/us/frustrate__us_1.mp3"},"examples":[{"en":"What frustrates him is that there's too little money to spend on the project.","cn":"使他懊恼的是可用于这个项目的资金太少。"},{"en":"The rescue attempt was frustrated by bad weather.","cn":"拯救行动因天气恶劣受阻。"}]},"frown":{"media":{"uk":"media/uk/frown__gb_1.mp3","us":"media/us/frown__us_1.mp3"},"oxford":{"phon":"fraʊn","pos":"verb","senses":[{"en":"to make a serious, angry or worried expression by bringing your eyebrows closer together so that lines appear on your forehead","cn":"皱眉；蹙额","ex":{"en":"What are you frowning at me for?","cn":"你为什么朝我皱眉头？"}},{"en":"a serious, angry or worried expression on a person’s face that causes lines on their forehead","cn":"皱眉；蹙额","ex":{"en":"A small frown creased her forehead.","cn":"她皱了一下眉头, 从而在前额上起了皱纹。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(因恼怒、担心、困惑、全神贯注等而)皱眉，蹙额","en":"When someone frowns, their eyebrows become drawn together, because they are annoyed, worried, or puzzled, or because they are concentrating.","ex":{"en":"Nancy shook her head, frowning","cn":"南希摇了摇头，皱着眉头。"}},{"pos":"PHRASAL VERB 短语动词","cn":"反对;不赞成;不同意","en":"If something is frowned upon or is frowned on people disapprove of it.","ex":{"en":"This practice is frowned upon as being wasteful","cn":"这种行为被认为是浪费而不获认可。"}},{"pos":"","cn":"","en":"相关词组：frown upon"}]},"examples":[{"en":"a slight frown of disapproval/concentration, etc.","cn":"略显不赞成的脸色、全神贯注地微皱眉头等"},{"en":"In her family, any expression of feeling was frowned upon.","cn":"她家里对任何感情的流露都不以为然。"}]},"freckled":{"media":{"uk":"media/uk/freckled__gb_1.mp3","us":"media/us/freckled__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"长有雀斑的;生有色斑的","en":"If a part of your body is freckled, it has freckles on it.","ex":{"en":"...a slight man with auburn hair and a freckled face.","cn":"一头红褐色头发、脸上长有雀斑的瘦小男子"}}]},"examples":[{"en":"a freckled face/schoolgirl","cn":"有雀斑的脸/女学生"}],"oxford":{"phon":"ˈfrekld","pos":"adjective","senses":[{"en":"having small, pale brown spots, especially on the face, that become darker after time spent in the sun","cn":"有雀斑的","ex":{"en":"a freckled face/schoolgirl","cn":"有雀斑的脸／女学生"}}]}},"frantic":{"media":{"uk":"media/uk/frantic__gb_1.mp3","us":"media/us/frantic__us_1.mp3"},"oxford":{"phon":"ˈfræntɪk","pos":"adjective","senses":[{"en":"done quickly and with a lot of activity, but in a way that is not very well organized","cn":"紧张忙乱的；手忙脚乱的","ex":{"en":"a frantic dash/search/struggle","cn":"不顾一切的猛冲；疯狂的搜查／斗争"}},{"en":"unable to control your emotions because you are extremely frightened or worried about something","cn":"（由于恐惧或担心）无法控制感情的，发狂似的","ex":{"en":"frantic with worry","cn":"忧虑得要命"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因害怕或担心)发狂的，狂躁的","en":"If you are frantic, you are behaving in a wild and uncontrolled way because you are frightened or worried.","ex":{"en":"A bird had been locked in and was by now quite frantic.","cn":"一只鸟被关进了笼子，到现在它都十分狂躁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"匆忙混乱的;紧张忙乱的","en":"If an activity is frantic, things are done quickly and in an energetic but disorganized way, because there is very little time.","ex":{"en":"A busy night in the restaurant can be frantic in the kitchen.","cn":"餐馆晚上生意好,厨房里可能会忙成一片。"}}]},"examples":[{"en":"Let's go back. Your parents must be getting frantic by now.","cn":"咱们回家吧。你的父母现在肯定快要急死了。"},{"en":"They made frantic attempts to revive him.","cn":"他们拼命地努力让他苏醒过来。"}]},"frightens":{"lemma":"frighten"},"fringe":{"oxford":{"phon":"frɪndʒ","pos":"noun","senses":[{"en":"the front part of somebody’s hair that is cut so that it hangs over their forehead","cn":"额前短垂发；刘海儿","g":"[countable, usually singular]","lab":"British English","ex":{"en":"She stared at us from beneath her fringe.","cn":"她的眼睛从刘海下盯着我们。"}},{"en":"a narrow border of hanging threads attached to the edge of something to decorate it","cn":"（某物的）穗，缘饰，流苏","g":"[countable]"},{"en":"a narrow area of trees, buildings, etc. along the edge of something","cn":"（沿…边缘的）一排（树木、房屋等）","g":"[countable]","ex":{"en":"a fringe of woodland","cn":"一条林带"}},{"en":"the outer edge of an area or a group","cn":"（地区或群体的）边缘","g":"[countable]","ex":{"en":"The factories are located on the northern fringes of the city.","cn":"这些工厂坐落在城市的北部边缘。"}},{"en":"groups of people, events and activities that are not part of the main group or activity","cn":"（指群体、事情或活动）次要部分，外围","g":"[singular]","ex":{"en":"Street musicians have been gathering as part of the festival fringe.","cn":"街头音乐人正聚集起来，为会演作助兴演出。"}},{"en":"to form a border around something","cn":"形成…的边缘","ex":{"en":"The beach was fringed by coconut palms.","cn":"沿海岸边长着椰子树。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"刘海儿;额前短垂发","en":"A fringe is hair which is cut so that it hangs over your forehead."},{"pos":"N-COUNT 可数名词","cn":"穗;流苏;缘饰","en":"A fringe is a decoration attached to clothes, or other objects such as curtains, consisting of a row of hanging strips or threads.","ex":{"en":"The jacket had leather fringes.","cn":"这件夹克有皮穗。"}},{"pos":"N-COUNT 可数名词","cn":"(某地的)周边，边缘","en":"To be on the fringe or the fringes of a place means to be on the outside edge of it, or to be in one of the parts that are farthest from its centre.","ex":{"en":"...black townships located on the fringes of the city","cn":"城市周边的黑人居住区"}},{"pos":"N-COUNT 可数名词","cn":"(某活动或机构的)次要部分，极端部分，外围","en":"The fringe or the fringes of an activity or organization are its less important, least typical, or most extreme parts, rather than its main and central part.","ex":{"en":"The party remained on the fringe of the political scene until last year.","cn":"直到去年为止这个政党一直处在政治舞台的外围。"}},{"pos":"ADJ 形容词","cn":"次要的;非主流的;外围的","en":"Fringe groups or events are less important or popular than other related groups or events.","ex":{"en":"The monarchists are a small fringe group who quarrel fiercely among themselves.","cn":"君主主义者是一个内部争吵激烈的非主流的小团体。"}}]},"media":{"img":["media/pic/hair_comp.jpg","media/thumb/pigtails.jpg"],"uk":"media/uk/fringe__gb_1.mp3","us":"media/us/fringe__us_1.mp3"},"examples":[{"en":"Street musicians have been gathering as part of the festival fringe.","cn":"街头音乐人正聚集起来，为会演作助兴演出。"},{"en":"Along the coast, an industrial fringe had already developed.","cn":"沿海岸一片带状工业区已发展起来。"}]},"frightened":{"media":{"uk":"media/uk/frightened__gb_1.mp3","us":"media/us/frightened__us_1.mp3"},"oxford":{"phon":"ˈfraɪtnd","pos":"adjective","senses":[{"en":"afraid; feeling fear","cn":"惊吓的；受惊的；害怕的","lab":"informal","ex":{"en":"a frightened child","cn":"受了惊吓的小孩"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受惊的;害怕的","en":"If you are frightened, you are anxious or afraid, often because of something that has just happened or that you think may happen.","ex":{"en":"She was frightened of flying","cn":"她害怕坐飞机。"}}]},"examples":[{"en":"I'm frightened of walking home alone in the dark.","cn":"我害怕在黑夜单独走路回家。"},{"en":"( informal ) I'd never do that. I'd be frightened to death.","cn":"我绝不会干。我会吓死的。"}],"base":"frighten"},"fruiterer":{"media":{"uk":"media/uk/fruiterer__gb_1.mp3","us":"media/us/fruiterer__us_1.mp3"},"oxford":{"phon":"ˈfruːtərə(r)","pos":"noun","senses":[{"en":"a person who owns or manages a shop selling fruit","cn":"水果商"}]}},"friday":{"media":{"uk":"media/uk/friday__gb_1.mp3","us":"media/us/friday__us_1.mp3"},"oxford":{"phon":"ˈfraɪdeɪ","pos":"noun","senses":[{"en":"the day of the week after Thursday and before Saturday","cn":"星期五","g":"[countable, uncountable]","lab":"informal or North American English","ex":{"en":"It's Friday today, isn't it?","cn":"今天是星期五，对吧？"}},{"en":"a character in Daniel Defoe's novel Robinson Crusoe. He becomes Crusoe's faithful servant after Crusoe saves him from being eaten by cannibals. The phrase Man Friday or Girl Friday was sometimes used to describe an assistant who did many different jobs in an office, but is now quite old-fashioned.","cn":"星期五：丹尼尔·迪福的小说《鲁滨逊漂流记》中的角色。克鲁索将他从食人族中救出后，他成为了克鲁索的忠实仆人。有时使用“男人星期五”或“女孩星期五”这个词来形容一个助理，他在办公室里做过许多不同的工作，但现在已经过时了。"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"星期五","en":"Friday is the day after Thursday and before Saturday.","ex":{"en":"Mr Cook is intending to go to the Middle East on Friday.","cn":"库克先生打算周五去中东。"}}]}},"frighten":{"oxford":{"phon":"ˈfraɪtn","pos":"verb","senses":[{"en":"to make somebody suddenly feel afraid","cn":"使惊吓；使惊恐","lab":"informal","ex":{"en":"Sorry, I didn't mean to frighten you.","cn":"对不起，我没有吓唬你的意思。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使惊恐;使害怕;吓唬","en":"If something or someone frightens you, they cause you to suddenly feel afraid, anxious, or nervous.","ex":{"en":"He knew that Soli was trying to frighten him, so he smiled to hide his fear","cn":"他知道索利是想吓唬他，所以他挤出笑容掩饰自己的恐惧。"}},{"pos":"PHRASE 短语","cn":"使吓得魂飞魄散;使吓破了胆","en":"If something frightens the life out of you, frightens the wits out of you, or frightens you out of your wits, it causes you to feel suddenly afraid or gives you a very unpleasant shock.","ex":{"en":"Fairground rides are intended to frighten the life out of you.","cn":"露天游乐场的飞车就是想把人吓丢了魂儿。"}},{"pos":"PHRASAL VERB 短语动词","cn":"吓跑;吓走;把…吓得躲远","en":"If you frighten away a person or animal or frighten them off, you make them afraid so that they run away or stay some distance away from you.","ex":{"en":"The fishermen said the company's seismic survey was frightening away fish","cn":"渔民们说这家公司进行的地震勘测把鱼都吓跑了。"}},{"pos":"PHRASAL VERB 短语动词","cn":"使吓得不敢打交道(或参与)","en":"To frighten someone away or frighten them off means to make them nervous so that they decide not to become involved with a particular person or activity.","ex":{"en":"Building society repossessions have frightened buyers off","cn":"建屋互助协会收回未偿清房贷的住房，这吓退了很多买家。"}},{"pos":"PHRASAL VERB 短语动词","cn":"吓得…做…","en":"If you frighten someone into doing something they would not normally do, you make them do it by making them afraid not to do it.","ex":{"en":"He was a bully. He tried to frighten people into doing what he wanted.","cn":"他恃强欺弱，总是想吓得人们按他的意愿做事。"}},{"pos":"","cn":"","en":"相关词组：frighten away frighten into frighten off"}]},"media":{"uk":"media/uk/frighten__gb_1.mp3","us":"media/us/frighten__us_1.mp3"},"examples":[{"en":"It alarms me that nobody takes this problem seriously.","cn":"谁都不认真对待这个问题，我非常担心。"},{"en":"He threatened the intruders with a gun and frightened them off.","cn":"他用枪威胁闯入者，把他们吓跑了。"}]},"freshman":{"media":{"uk":"media/uk/freshman__gb_1.mp3","us":"media/us/freshman__us_1.mp3"},"oxford":{"phon":"ˈfreʃmən","pos":"noun","senses":[{"en":"a first-year student at a university or college","cn":"大学一年级新生","ex":{"en":"college freshmen","cn":"大学一年级新生"}},{"en":"a first-year student at high school or junior high school","cn":"高中一年级学生；初中一年级学生","ex":{"en":"high school freshmen","cn":"高中一年级新生"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(美国大学)一年级新生","en":"In America, a freshman is a student who is in his or her first year at university or college."}]},"examples":[{"en":"high school/college freshmen","cn":"中学/大学一年级新生"},{"en":"during my freshman year","cn":"在我一年级期间"}]},"front":{"media":{"uk":"media/uk/front__gb_1.mp3","us":"media/us/front__us_1.mp3"},"oxford":{"phon":"frʌnt","pos":"noun","senses":[{"en":"the part or side of something that faces forward; the side of something that you look at first","cn":"正面","g":"[countable, usually singular]","sc":"forward part/position","ex":{"en":"The front of the building was covered with ivy.","cn":"大楼的正面爬满了常春藤。"}},{"en":"the position that is directly ahead of somebody/something","cn":"前面；正前方","g":"[singular]","sc":"forward part/position","ex":{"en":"I turned round to face the front.","cn":"我转身面对前方。"}},{"en":"the part of something that is furthest forward","cn":"前部","g":"[singular]","sc":"forward part/position","ex":{"en":"The singer came to the front of the stage.","cn":"歌手走到舞台的前面。"}},{"en":"the part of somebody’s body that faces forwards","cn":"身体前部","g":"[singular]","sc":"chest","ex":{"en":"She was lying on her front.","cn":"她俯卧着。"}},{"en":"the side of a large building, especially a church, that faces west, north, etc.","cn":"（建筑物，尤指教堂朝西、北、东、南等的）面","g":"[countable]","sc":"side of building","ex":{"en":"the west front of the cathedral","cn":"大教堂的西侧"}},{"en":"the road or area of land along the edge of the sea, a lake or a river","cn":"海滨；湖畔；河边；沿海（或湖、河）道路","g":"[singular]","lab":"British English","sc":"edge of sea/lake","ex":{"en":"Couples walked hand in hand along the front.","cn":"对对情侣手牵手沿河边散步。"}},{"en":"an area where fighting takes place during a war","cn":"前线；前方","g":"[countable, usually singular]","sc":"in war","ex":{"en":"More British troops have been sent to the front.","cn":"更多的英国部队已派往前线。"}},{"en":"a particular area of activity","cn":"活动领域；阵线","g":"[countable]","sc":"area of activity","ex":{"en":"Things are looking unsettled on the economic front.","cn":"经济战线上的情况显得不稳定。"}},{"en":"behaviour that is not what it appears to be, done in order to hide somebody's true feelings or opinions","cn":"表面；外表","g":"[singular]","sc":"hiding true feelings","ex":{"en":"It's not always easy to put on a brave front for the family.","cn":"为家人装出勇敢的样子并不总是容易的事。"}},{"en":"a person or an organization that is used to hide an illegal or secret activity","cn":"非法（或秘密）活动掩护者","g":"[countable, usually singular]","sc":"hiding something illegal","ex":{"en":"The travel company is just a front for drug trafficking.","cn":"这家旅行社不过是毒品交易的掩护场所。"}},{"en":"used in the names of some political organizations","cn":"（用于政治组织的名称）阵线","g":"[singular]","sc":"political organization","ex":{"en":"the Animal Liberation Front","cn":"动物解放阵线"}},{"en":"the line where a mass of cold air meets a mass of warm air","cn":"（冷暖气团接触的）锋","g":"[countable]","sc":"weather","ex":{"en":"a cold/warm front","cn":"冷锋；暖锋"}},{"en":"on or at the front of something","cn":"前面的；前部的；在前的；正面的","lab":"British English","ex":{"en":"the front garden","cn":"前花园"},"pos":"adjective"},{"en":"produced with the front of the tongue in a higher position than the back, for example /iː/ in English","cn":"舌前位发的；舌前的","lab":"phonetics","pos":"adjective"},{"en":"to face something or be in front of something; to have the front pointing towards something","cn":"面向；在…前面；朝；向","g":"[transitive, intransitive]","sc":"face something","ex":{"en":"The cathedral fronts the city's main square.","cn":"大教堂面向城市的主广场。"},"pos":"verb"},{"en":"having the front made of or covered with something","cn":"用…作正面；用…覆盖正面","sc":"-fronted","ex":{"en":"a glass-fronted bookcase","cn":"正面是玻璃的书柜"},"pos":"verb"},{"en":"to lead or represent an organization, a group, etc.","cn":"领导，代表（团体、组织等）","g":"[transitive]","sc":"lead group","ex":{"en":"He fronts a multinational company.","cn":"他领导一家跨国公司。"},"pos":"verb"},{"en":"to present a television programme, a show, etc.","cn":"主持（电视节目、演出等）","g":"[transitive]","lab":"especially British English","sc":"present TV programme","ex":{"en":"The former footballer will front a new television sports quiz.","cn":"这位前足球运动员将参加一项新的电视体育测验。"},"pos":"verb"},{"en":"to give more importance to a part of a sentence by placing it at or near the beginning of the sentence, as in ‘That I would like to see.’","cn":"（为强调而）将（句子某一部分）前置","g":"[transitive]","lab":"linguistics","sc":"grammar","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"前面;前部;正面","en":"The front of something is the part of it that faces you, or that faces forward, or that you normally see or use.","ex":{"en":"One man sat in an armchair, and the other sat on the front of the desk","cn":"一个男人坐在扶手椅里，另一个坐在桌子前面。"}},{"pos":"N-COUNT 可数名词","cn":"(建筑物)临街的一面，正面","en":"The front of a building is the side or part of it that faces the street.","ex":{"en":"Attached to the front of the house, there was a large veranda.","cn":"房子的正面有一条宽大的游廊。"}},{"pos":"N-SING 单数名词","cn":"(人或动物的)身体前部，前身,胸部","en":"A person's or animal's front is the part of their body between their head and their legs that is on the opposite side to their back.","ex":{"en":"If you lie your baby on his front, he'll lift his head and chest up.","cn":"如果让宝宝俯卧，他会把头和胸抬起。"}},{"pos":"ADJ 形容词","cn":"前面的;前部的;正面的;(位置)在前的","en":"Front is used to refer to the side or part of something that is towards the front or nearest to the front.","ex":{"en":"I went out there on the front porch","cn":"我出来走到前廊上。"}},{"pos":"ADJ 形容词","cn":"(报纸)头(版)的，首(页)的","en":"The front page of a newspaper is the outside of the first page, where the main news stories are printed.","ex":{"en":"The Guardian's front page carries a photograph of the two foreign ministers","cn":"《卫报》的头版刊登了两国外交部长的一张合影。"}},{"pos":"N-SING 单数名词","cn":"海滨道","en":"The front is a road next to the sea in a seaside town.","ex":{"en":"...a stroll on the front","cn":"漫步于海滨道"}},{"pos":"N-COUNT 可数名词","cn":"(战争中的)前线，前方","en":"In a war, the front is a line where two opposing armies are facing each other.","ex":{"en":"Sonja's husband is fighting at the front.","cn":"索尼娅的丈夫正在前线打仗。"}},{"pos":"N-COUNT 可数名词","cn":"(某个)方面，领域","en":"If you say that something is happening on a particular front, you mean that it is happening with regard to a particular situation or field of activity.","ex":{"en":"...research across a wide academic front","cn":"跨多个学术领域的研究"}},{"pos":"N-COUNT 可数名词","cn":"(装出的)样子;假面具","en":"If someone puts on a particular kind of front, they pretend to have a particular quality.","ex":{"en":"Michael kept up a brave front both to the world and in his home","cn":"迈克尔对外界和家人都表现出一副勇敢的样子。"}},{"pos":"N-COUNT 可数名词","cn":"(非法或秘密的组织或活动的)掩护，幌子","en":"An organization or activity that is a front for one that is illegal or secret is used to hide it.","ex":{"en":"...a firm later identified by the police as a front for crime syndicates","cn":"后经警方确认为犯罪集团幌子的一家公司"}},{"pos":"N-COUNT 可数名词","cn":"(冷热空气交汇的)锋","en":"In relation to the weather, a front is a line where a mass of cold air meets a mass of warm air.","ex":{"en":"The snow signaled the arrival of a front, and a high-pressure area seemed to be settling in","cn":"下雪预示着冷热空气的交锋，而一个高气压区似乎也将到来并可能持续。"}},{"pos":"N-IN-NAMES 名称名词","cn":"(常用于政治组织名称中)阵线","en":"Front is often used in the titles of political organizations with a particular aim.","ex":{"en":"...the People's Liberation Front.","cn":"人民解放阵线"}},{"pos":"VERB 动词","cn":"面对;朝向","en":"A building or an area of land that fronts a particular place or fronts onto it is next to it and faces it.","ex":{"en":"...real estate, which includes undeveloped land fronting the city convention center","cn":"包括城市会议中心对面未开发土地的房地产"}},{"pos":"VERB 动词","cn":"领导;作为…的领袖","en":"The person who fronts an organization is the most senior person in it.","ex":{"en":"He fronted a formidable band of fighters","cn":"他率领着一队可畏的斗士。"}},{"pos":"VERB 动词","cn":"作为…的主唱","en":"The person who fronts a pop group or rock band is the main singer.","ex":{"en":"He also fronted a group called Haircuts That Kill.","cn":"他还是一个叫做“酷炫发式”乐队的主唱。"}},{"pos":"PHRASE 短语","cn":"在前面;在最前头","en":"If a person or thing is in front, they are ahead of others in a moving group, or further forward than someone or something else.","ex":{"en":"Officers will crack down on lunatic motorists who speed or drive too close to the car in front","cn":"警察将会严厉打击超速或是紧贴前车行驶的疯狂司机。"}},{"pos":"PHRASE 短语","cn":"(在竞赛或比赛中)处于领先位置","en":"Someone who is in front in a competition or contest at a particular point is winning at that point.","ex":{"en":"Richard Dunwoody is in front in the jockeys' title race","cn":"理查德·邓伍迪在职业赛马骑师冠军赛中领先其他选手。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…前面;靠近…前部","en":"If someone or something is in front of a particular thing, they are facing it, ahead of it, or close to the front part of it.","ex":{"en":"She sat down in front of her dressing-table mirror to look at herself","cn":"她在梳妆台的镜子前面坐下端详自己。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在…面前(做或说);当着…的面","en":"If you do or say something in front of someone else, you do or say it when they are present.","ex":{"en":"They never argued in front of their children","cn":"他们从来不当着孩子的面争吵。"}},{"pos":"PHRASE 短语","cn":"在国内方面","en":"On the home front or on the domestic front means with regard to your own country rather than foreign countries.","ex":{"en":"Its present economic ills on the home front are largely the result of overspending","cn":"它目前国内方面的经济弊病主要源自支出过度。"}}]},"examples":[{"en":"There’s a bus stop in front of the house (= on the same side of the road).","cn":"房子前面有一个公共汽车站（在公路的这面）。"},{"en":"There’s a bus stop opposite the house (= on the other side of the road).","cn":"房子对面有一个公共汽车站（在公路的对面）。"}]},"free":{"media":{"uk":"media/uk/free__gb_1.mp3","us":"media/us/free__us_1.mp3"},"oxford":{"phon":"friː","pos":"adjective","senses":[{"en":"without particular plans or arrangements; not busy","cn":"没有安排活动的；空闲的","sc":"not busy","ex":{"en":"Are you free on Saturday? We're having a barbecue.","cn":"你星期六有空吗？我们要搞烧烤聚餐。"}},{"en":"not being used","cn":"未使用","sc":"not being used","ex":{"en":"He held out his free hand and I took it.","cn":"他伸出空着的一只手，我就抓住了。"}},{"en":"costing nothing","cn":"不收费的","sc":"no payment","ex":{"en":"Admission is free.","cn":"免费入场。"}},{"en":"not under the control or in the power of somebody else; able to do what you want","cn":"能随自己意愿的；随心所欲的","sc":"not controlled","ex":{"en":"I have no ambitions other than to have a happy life and be free.","cn":"我没有雄心大志，只求自由自在地过幸福生活。"}},{"en":"not limited or controlled by anyone else","cn":"不受限制的；不受控制的","sc":"not controlled","ex":{"en":"A true democracy needs free speech and a free press.","cn":"真正的民主需要言论自由和新闻自由。"}},{"en":"not a prisoner or slave","cn":"自由的（不是囚犯或奴隶）","sc":"not prisoner","ex":{"en":"He walked out of jail a free man.","cn":"他获释出狱，成为自由人。"}},{"en":"not tied up or in a cage","cn":"未拴住的；非关在笼中的","sc":"animal/bird","ex":{"en":"The researchers set the birds free.","cn":"研究人员把鸟放了。"}},{"en":"clear; not blocked","cn":"无阻碍的；畅通的","sc":"not blocked","ex":{"en":"Ensure there is a free flow of air around the machine.","cn":"要确保机器周围空气畅通。"}},{"en":"not containing or affected by something harmful or unpleasant","cn":"不含有害物的；不受…伤害（或影响等的）","sc":"without something","ex":{"en":"free from artificial colours and flavourings","cn":"不含人工色素和人工调味料"}},{"en":"without the thing mentioned","cn":"没有…的","sc":"without something","ex":{"en":"pure, additive-free ingredients","cn":"纯粹而无添加剂的原料"}},{"en":"not attached to something; not stuck somewhere and unable to move","cn":"未固定的；未缚住的","sc":"not attached/able to move","ex":{"en":"Pull gently on the free end of the rope.","cn":"轻拉绳索松开的一端。"}},{"en":"ready to give something, especially when it is not wanted","cn":"随便给出的","lab":"often disapproving","sc":"ready to give","ex":{"en":"He's too free with his opinions.","cn":"他太随便发表意见了。"}},{"en":"a free translation is not exact but gives the general meaning","cn":"不拘泥原文的；（翻译）根据大意的；意译的","sc":"translation"},{"en":"without payment","cn":"不需付款","sc":"without payment","ex":{"en":"Children under five travel free.","cn":"五岁以下儿童免费乘坐。"},"pos":"adverb"},{"en":"in a way that is not tied but is able to move about","cn":"未固定地；未缚住地","sc":"not tied","ex":{"en":"Attach the top and let the ends hang free.","cn":"固定住顶部，让末端自由下垂。"},"pos":"adverb"},{"en":"to allow somebody to leave prison or somewhere they have been kept against their will","cn":"释放；使摆脱","sc":"prisoner","ex":{"en":"The hijackers agreed to free a further ten hostages.","cn":"劫持者同意再释放十名人质。"},"pos":"verb"},{"en":"to move somebody/something that is caught or fixed on something","cn":"释放；使摆脱","sc":"somebody/something trapped","ex":{"en":"She struggled to free herself.","cn":"她挣扎着以求脱身。"},"pos":"verb"},{"en":"to remove something that is unpleasant or not wanted from somebody/something","cn":"解除（或去除、清除）","sc":"remove something","ex":{"en":"These exercises help free the body of tension.","cn":"这些锻炼可使紧张的身体放松。"},"pos":"verb"},{"en":"to make somebody/something available for a particular purpose","cn":"使可用（于某目的）","sc":"make available","ex":{"en":"We freed time each week for a project meeting.","cn":"我们每周都腾出时间开一次项目会议。"},"pos":"verb"},{"en":"to give somebody the extra time to do something that they want to do","cn":"使能腾出时间","sc":"make available","ex":{"en":"Winning the prize freed him to paint full-time.","cn":"获奖使他能腾出时间整天作画。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"免费的","en":"If something is free, you can have it or use it without paying for it.","ex":{"en":"The seminars are free, with lunch provided.","cn":"研讨会不收会务费，而且还提供午餐。"}},{"pos":"","cn":"","en":"free of charge→see: ;"},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自由的;不受约束的;没有限制的","en":"Someone or something that is free is not restricted, controlled, or limited, for example by rules, customs, or other people.","ex":{"en":"The government will be free to pursue its economic policies","cn":"政府将可不受限制地实行其经济政策。"}},{"pos":"VERB 动词","cn":"使摆脱;使去掉","en":"If you free someone of something that is unpleasant or restricting, you remove it from them.","ex":{"en":"It will free us of a whole lot of debt","cn":"它会使我们摆脱巨额债务。"}},{"pos":"ADJ 形容词","cn":"(人身)自由的;不受监禁(或奴役)的","en":"Someone who is free is no longer a prisoner or a slave.","ex":{"en":"He walked from the court house a free man","cn":"他以自由之身走出了法院。"}},{"pos":"VERB 动词","cn":"使人身自由;解放;释放","en":"To free a prisoner or a slave means to let them go or release them from prison.","ex":{"en":"Israel is set to free more Lebanese prisoners","cn":"以色列准备释放更多的黎巴嫩犯人。"}},{"pos":"ADJ 形容词","cn":"无…的;摆脱了…的","en":"If someone or something is free of or free from an unpleasant thing, they do not have it or they are not affected by it.","ex":{"en":"...a future far more free of fear","cn":"远远摆脱恐惧的未来"}},{"pos":"ADJ 形容词","cn":"免(税)的","en":"A sum of money or type of goods that is free of tax or duty is one that you do not have to pay tax on."},{"pos":"VERB 动词","cn":"使解脱出来;使空出来","en":"To free someone or something means to make them available for a task or function that they were previously not available for.","ex":{"en":"Toolbelts free both hands and lessen the risk of dropping hammers","cn":"工具腰带解放了双手，还减少了锤子掉落的风险。"}},{"pos":"ADJ 形容词","cn":"空闲的;有空的;不上班的;不在忙的","en":"If you have a free period of time or are free at a particular time, you are not working or occupied then.","ex":{"en":"She spent her free time shopping","cn":"她空闲的时候就去购物。"}},{"pos":"ADJ 形容词","cn":"不在用的;无人使用的;未被占用的","en":"If something such as a table or seat is free, it is not being used or occupied by anyone, or is not reserved for anyone to use.","ex":{"en":"There was only one seat free on the train","cn":"列车上只剩下一个空座。"}},{"pos":"ADJ 形容词","cn":"松开的;脱开的;未缚住的;未固定的","en":"If you get something free or if it gets free, it is no longer trapped by anything or attached to anything.","ex":{"en":"The severe conditions hampered attempts to pull the vessel free of the rig","cn":"恶劣的天气情况使得把那艘船拉离钻塔的努力很难奏效。"}},{"pos":"VERB 动词","cn":"松开;解开;使不再缚住(或固定)","en":"If you free someone or something, you remove them from the place in which they have been trapped or become fixed.","ex":{"en":"It took firemen two hours to cut through the drive belt to free him","cn":"消防员花了两个小时才把传动带切断，把他救了出来。"}},{"pos":"ADJ 形容词","cn":"(手或胳膊)空着的，闲着的","en":"When someone is using one hand or arm to hold or move something, their other hand or arm is referred to as their free one.","ex":{"en":"He snatched up the receiver and his free hand groped for the switch on the bedside lamp","cn":"他一只手抓起电话听筒，另一只手去摸床头灯的开关。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"慷慨的;大手大脚的;过分给予的","en":"If you say that someone is free with something such as advice or money, you mean that they give a lot of it, sometimes when it is not wanted.","ex":{"en":"They weren't always so free with their advice","cn":"他们并不是一直都如此好为人师。"}},{"pos":"PHRASE 短语","cn":"请随意;不必拘谨","en":"You say 'feel free' when you want to give someone permission to do something, in a very willing way.","ex":{"en":"Go right ahead. Feel free","cn":"开始吧。请便。"}},{"pos":"PHRASE 短语","cn":"义务地;无偿地;免费地","en":"If you do something or get something for free, you do it without being paid or get it without having to pay for it.","ex":{"en":"I wasn't expecting you to do it for free","cn":"我并没有指望你白干。"}},{"pos":"PHRASE 短语","cn":"(表达批评意见时用于强调)不管怎样","en":"You say that you will express a critical opinion about something for free when you want to emphasize how strongly you feel about it.","ex":{"en":"I'll tell you one thing for free: I can't stand him.","cn":"不管怎样我都要说：我受不了他。"}},{"pos":"","cn":"","en":"to give someone a free hand→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"开放，放开(市场、经济或体系)","en":"To free up a market, economy, or system means to make it operate with fewer restrictions and controls.","ex":{"en":"...policies for freeing up markets and extending competition.","cn":"开放市场、扩大竞争的政策"}},{"pos":"","cn":"","en":"相关词组：free up"}]},"examples":[{"en":"By the end of May nearly 100 of an estimated 2 000 political prisoners had been freed.","cn":"至五月底，估计 2 000 名政治犯中有近 100 人已经获释。"},{"en":"A true democracy complete with free speech and a free press was called for.","cn":"人们呼吁要有包括言论自由和新闻自由在内的真正民主。"}]},"frigid":{"media":{"uk":"media/uk/frigid__gb_1.mp3","us":"media/us/frigid__us_1.mp3"},"oxford":{"phon":"ˈfrɪdʒɪd","pos":"adjective","senses":[{"en":"very cold","cn":"寒冷的；严寒的","ex":{"en":"frigid air","cn":"冰冷的空气"}},{"en":"not showing any friendly or kind feelings","cn":"冷淡的；不友好的","ex":{"en":"a frigid voice","cn":"冷冰冰的声音"}},{"en":"not able to enjoy sex","cn":"性冷淡的；达不到性高潮的","lab":"old-fashioned"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"寒冷的;极冷的","en":"Frigid means extremely cold.","ex":{"en":"A snowstorm hit the West today, bringing with it frigid temperatures","cn":"暴风雪今天袭击了西部地区，导致气温骤降。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(女子)性冷淡的","en":"If a woman is frigid, she finds it difficult to become sexually aroused. You can often use frigid to show disapproval.","ex":{"en":"My husband says I am frigid.","cn":"丈夫说我性冷淡。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"拘谨的;冷淡的;不友好的","en":"If you describe the atmosphere in a place or someone's behaviour as frigid, you mean that it is very formal and unfriendly.","ex":{"en":"He presided at all councils of ministers, where the atmosphere could be frigid on occasions","cn":"所有的内阁会议都由他主持，有时会上的气氛会很拘谨。"}}]},"examples":[{"en":"There was a frigid atmosphere in the room.","cn":"房间里一片冷淡的气氛。"},{"en":"a frigid voice","cn":"冷冰冰的声音"}]},"friend":{"media":{"uk":"media/uk/friend__gb_1.mp3","us":"media/us/friend__us_1.mp3"},"oxford":{"phon":"frend","pos":"noun","senses":[{"en":"a person you know well and like, and who is not usually a member of your family","cn":"朋友；友人","sc":"person you like","ex":{"en":"This is my friend Tom.","cn":"这是我的朋友汤姆。"}},{"en":"a person who is on your list of contacts on a social media website","cn":"（社交网站上的）好友，联系人","sc":"on the internet","ex":{"en":"How many friends have you got on Facebook?","cn":"你在脸书上有多少好友？"}},{"en":"a person who supports an organization, a charity, etc., especially by giving or raising money; a person who supports a particular idea, etc.","cn":"赞助者；支持者","sc":"supporter","ex":{"en":"the Friends of St Martin’s Hospital","cn":"圣马丁医院的赞助者"}},{"en":"a person who has the same interests and opinions as yourself, and who will help and support you","cn":"自己人；同志；同伙；同盟者","sc":"not enemy","ex":{"en":"His eyes were moving from face to face: friend or foe?","cn":"他的目光从一张脸移到另一张脸：是友是敌？"}},{"en":"used to talk about or to somebody that you meet who is not actually a friend","cn":"那家伙，老兄（称呼偶遇的不相识的人）","lab":"often ironic","sc":"person that you meet/speak to","ex":{"en":"I wish our friend at the next table would shut up.","cn":"但愿我们邻桌那位仁兄闭嘴。"}},{"en":"used by a member of parliament to refer to another member of parliament or by a lawyer to refer to another lawyer in a court of law","cn":"（议员间或律师间的一种称呼）朋友，阁下，同人","sc":"in parliament/court","ex":{"en":"my honourable friend, the member for Henley (= in the House of Commons)","cn":"我尊敬的朋友亨利区议员（下院用语）"}},{"en":"a member of the Society of Friends","cn":"（新教）公谊会成员","sc":"in religion"},{"en":"to add somebody to your list of contacts on a social media website","cn":"（在社交媒体上）加为好友，关注","ex":{"en":"The chat system only allows you to communicate with those you have friended on the site.","cn":"这个聊天系统只允许你和你在网站上加为好友的人交流。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"朋友;友人","en":"A friend is someone who you know well and like, but who is not related to you.","ex":{"en":"I had a long talk about this with my best friend","cn":"我和我最好的朋友就此事进行了长谈。"}},{"pos":"N-PLURAL 复数名词","cn":"(与…互为)朋友","en":"If you are friends with someone, you are their friend and they are yours.","ex":{"en":"I still wanted to be friends with Alison","cn":"我还是想和艾莉森做朋友。"}},{"pos":"N-PLURAL; N-IN-NAMES 复数名词；名称名词","cn":"支持者;拥护者;赞助者","en":"The friends of a country, cause, organization, or a famous politician are the people and organizations who help and support them.","ex":{"en":"...the friends of Israel.","cn":"以色列的支持者"}},{"pos":"N-COUNT 可数名词","cn":"盟友;友国;友邦","en":"If one country refers to another as a friend, they mean that the other country is not an enemy of theirs.","ex":{"en":"The president said that Japan is now a friend and international partner.","cn":"总统说日本现在是盟友和国际合作伙伴。"}},{"pos":"PHR-RECIP 相互短语","cn":"(与…)交朋友;(和…)建立友谊","en":"If you make friends with someone, you begin a friendship with them. You can also say that two people make friends .","ex":{"en":"He has made friends with the kids on the street","cn":"他和流浪街头的孩子交上了朋友。"}}]},"examples":[{"en":"my honourable friend , the member for Henley (= in the House of Commons)","cn":"我尊敬的朋友亨利区议员（下院用语）"},{"en":"They had a quarrel, but they're friends again now.","cn":"他们吵过架，不过现在又和好了。"}]},"freezing":{"media":{"uk":"media/uk/freezing__gb_1.mp3","us":"media/us/freezing__us_1.mp3"},"oxford":{"phon":"ˈfriːzɪŋ","pos":"adjective","senses":[{"en":"extremely cold","cn":"极冷的；冻僵的","ex":{"en":"It's freezing in here!","cn":"这儿冷得不得了！"}},{"en":"having temperatures that are below 0° Celsius","cn":"冰冻的；冰点以下的","g":"[only before noun]","ex":{"en":"Expect icy roads and freezing fog tonight.","cn":"预计今晚路面会结冰，还会出现冰雾。"}},{"en":"0° Celsius, the temperature at which water freezes","cn":"冰点","ex":{"en":"Tonight temperatures will wall well below freezing.","cn":"今晚气温将远低于冰点。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极冷的;冻得彻骨的","en":"If you say that something is freezing or freezing cold, you are emphasizing that it is very cold. →see usage note at:","ex":{"en":"The cinema was freezing.","cn":"电影院太冷了。"}},{"pos":"ADJ 形容词","cn":"(人)感到极冷的，冻得要命的","en":"If you say that you are freezing or freezing cold, you emphasizing that you feel very cold.","ex":{"en":"'You must be freezing,' she said.","cn":"“你一定冻坏了，”她说。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同 freezing point","en":"Freezing means the same as freezing point .","ex":{"en":"It's 15 degrees below freezing.","cn":"温度为零下 15 度。"}}]},"examples":[{"en":"It's freezing in here!","cn":"这儿冷得不得了！"},{"en":"( informal ) It's freezing cold outside.","cn":"外面极为寒冷。"}],"base":"freeze"},"frosting":{"oxford":{"phon":"ˈfrɒstɪŋ","pos":"noun","senses":[{"en":"a sweet mixture of sugar and water, milk, butter or egg white that is used to cover and decorate cakes","cn":"糖霜（用以装饰糕饼等）","lab":"North American English"},{"en":"the crime of stealing a vehicle that has been left with the engine running in cold weather so that the engine warms up","cn":"（冷天趁发动机预热车辆无人看管时下手的）盗窃车辆罪","lab":"British English","ex":{"en":"Police issued the annual winter warning against frosting car crime.","cn":"警方发布年度冬季警告，防止汽车结霜犯罪。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(用于装点糕饼的)糖霜","en":"Frosting is a sweet substance made from powdered sugar that is used to cover and decorate cakes.","ex":{"en":"...a huge pastry with green frosting on it.","cn":"撒有绿色糖霜的一大块油酥糕点"}}]},"media":{"uk":"media/uk/frosting__gb_1.mp3","us":"media/us/frosting__us_1.mp3"},"base":"frost"},"frustrating":{"media":{"uk":"media/uk/frustrating__gb_1.mp3","us":"media/us/frustrating__us_1.mp3"},"oxford":{"phon":"frʌˈstreɪtɪŋ","pos":"adjective","senses":[{"en":"causing you to feel annoyed and impatient because you cannot do or achieve what you want","cn":"令人懊恼的；令人沮丧的","ex":{"en":"It's frustrating to have to wait so long.","cn":"要等这么长时间，真令人懊恼。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人灰心的;使人沮丧的;让人懊恼的","en":"Something that is frustrating annoys you or makes you angry because you cannot do anything about the problems it causes.","ex":{"en":"The current situation is very frustrating for us","cn":"当前的情形令我们十分灰心。"}}]},"examples":[{"en":"It's frustrating to have to wait so long.","cn":"要等这么长时间，真令人懊恼。"},{"en":"Progress was frustratingly slow.","cn":"进展慢得使人沮丧。"}],"base":"frustrate"},"french":{"media":{"uk":"media/uk/french__gb_1.mp3","us":"media/us/french__us_1.mp3"},"oxford":{"phon":"frentʃ","pos":"adjective","senses":[{"en":"of or connected with France, its people or its language","cn":"法国的；法国人的；法语的"},{"en":"the language of France and some other countries","cn":"法语","g":"[uncountable]","pos":"noun"},{"en":"the people of France","cn":"法国人","g":"[plural]","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"法国的;法国人的;法语的;法国文化的","en":"French means belonging or relating to France, or its people, language, or culture.","ex":{"en":"...the French parliament","cn":"法国议会"}},{"pos":"N-PLURAL 复数名词","cn":"(总称)法国人","en":"The French are the people who come from France.","ex":{"en":"Two-thirds of the French are in favour of limiting foreign imports into Europe.","cn":"三分之二的法国人赞成限制欧洲的进口贸易。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"法语","en":"French is the language spoken by people who live in France and in parts of some other countries, including Belgium, Canada, and Switzerland.","ex":{"en":"The villagers spoke French.","cn":"村民们讲法语。"}}]},"examples":[{"en":"How do you ask for directions in French?","cn":"用法语怎么问路？"},{"en":"an excellent French wine","cn":"上等的法国葡萄酒"}]},"fret":{"oxford":{"phon":"fret","pos":"verb","senses":[{"en":"to be worried or unhappy and not able to relax","cn":"苦恼；烦躁；焦虑不安","ex":{"en":"Her baby starts to fret as soon as she goes out of the room.","cn":"她一走出房间，婴儿就躁动起来。"}},{"en":"one of the bars on the long thin part of a guitar, etc. Frets show you where to press the strings with your fingers to produce particular sounds.","cn":"（吉他等指板上定音的）品","ex":{"en":"a rock guitar with a 24 fret neck","cn":"带有 24 品琴颈的摇滚吉他"},"pos":"noun"},{"en":"mist or fog that comes in from the sea","cn":"（从海上飘来的）雾气，薄雾，雾","lab":"Northern British English","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"苦恼;烦恼;发愁","en":"If you fret about something, you worry about it.","ex":{"en":"I was working all hours and constantly fretting about everyone else's problems","cn":"我一刻不闲地工作，总是为别人的事操心。"}},{"pos":"N-COUNT 可数名词","cn":"(吉他等弦乐器琴颈处的)品","en":"The frets on a musical instrument such as a guitar are the raised lines across its neck."}]},"media":{"uk":"media/uk/fret__gb_1.mp3","us":"media/us/fret__us_1.mp3"},"examples":[{"en":"Her baby starts to fret as soon as she goes out of the room.","cn":"她一走出房间，婴儿就躁动起来。"},{"en":"Fretting about it won't help.","cn":"苦恼于事无补。"}]},"freedom":{"oxford":{"phon":"ˈfriːdəm","pos":"noun","senses":[{"en":"the power or right to do or say what you want without anyone stopping you","cn":"（指权利）自由","g":"[uncountable, countable]","ex":{"en":"Press freedom is under attack.","cn":"新闻自由受到攻击。"}},{"en":"the state of not being a prisoner or slave","cn":"自由民地位（不是囚犯或奴隶）","g":"[uncountable]","ex":{"en":"He finally won his freedom after twenty years in jail.","cn":"他蹲了二十年监狱以后终于获得了自由。"}},{"en":"the state of not being ruled by a foreign or cruel government","cn":"自由（不受外国或专制政府的统治）","g":"[uncountable]","ex":{"en":"We believe in freedom and democracy.","cn":"我们信仰自由和民主。"}},{"en":"the state of being able to move easily","cn":"自由（可以活动自如）","g":"[uncountable]","ex":{"en":"The skirt has a side split for freedom of movement.","cn":"这条裙子侧边开衩，方便活动。"}},{"en":"the state of not being affected by the thing mentioned","cn":"没有…的情况；不受…影响的状态","g":"[uncountable]","ex":{"en":"All people should be guaranteed freedom from fear.","cn":"人人都应该有免于恐惧的保障。"}},{"en":"permission to use something without limits","cn":"自由使用权","g":"[singular]","ex":{"en":"I was given the freedom of the whole house.","cn":"我获得整座房子的自由使用权。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自由;自由行为","en":"Freedom is the state of being allowed to do what you want to do. Freedoms are instances of this.","ex":{"en":"...freedom of speech","cn":"言论自由"}},{"pos":"N-UNCOUNT 不可数名词","cn":"人身自由;自由身份","en":"When prisoners or slaves are set free or escape, they gain their freedom .","ex":{"en":"...the agreement worked out by the UN, under which all hostages and detainees would gain their freedom.","cn":"联合国拟定的恢复所有人质和被拘禁者人身自由的协议"}},{"pos":"N-UNCOUNT 不可数名词","cn":"摆脱;免除;不受…影响的状态","en":"Freedom from something you do not want means not being affected by it.","ex":{"en":"...all the freedom from pain that medicine could provide.","cn":"医药可以提供的对痛苦的解脱"}},{"pos":"N-SING 单数名词","cn":"(某市的)荣誉市民称号","en":"The freedom of a particular city is a special honour which is given to a famous person who is connected with that city, or to someone who has performed some special service for the city.","ex":{"en":"He was given the Freedom of the City of Dublin by the Lord Mayor.","cn":"市长阁下亲自向他颁发了都柏林市荣誉市民称号。"}}]},"media":{"uk":"media/uk/freedom__gb_1.mp3","us":"media/us/freedom__us_1.mp3"},"examples":[{"en":"Thanks to the automobile, Americans soon had a freedom of movement previously unknown.","cn":"由于有了汽车，美国人很快就获得了前所未有的行动自由。"},{"en":"He finally won his freedom after twenty years in jail.","cn":"他蹲了二十年监狱以后终于获得了自由。"}]},"frightening":{"media":{"uk":"media/uk/frightening__gb_1.mp3","us":"media/us/frightening__us_1.mp3"},"oxford":{"phon":"ˈfraɪtnɪŋ","pos":"adjective","senses":[{"en":"making you feel afraid","cn":"引起恐惧的；使惊恐的；骇人的","ex":{"en":"a frightening experience/prospect/thought","cn":"可怕的经历／前景／想法"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人惊恐的;令人害怕的;骇人的","en":"If something is frightening, it makes you feel afraid, anxious, or nervous.","ex":{"en":"It was a very frightening experience and they were very courageous","cn":"那段经历太恐怖了，他们表现得非常勇敢。"}}]},"examples":[{"en":"It's frightening to think it could happen again.","cn":"想到此事可能再次发生就使人不寒而栗。"},{"en":"a frightening experience/prospect/thought","cn":"可怕的经历/景象/想法"}],"base":"frighten"},"framework":{"oxford":{"phon":"ˈfreɪmwɜːk","pos":"noun","senses":[{"en":"the parts of a building or an object that support its weight and give it shape","cn":"（建筑物或物体的）构架，框架，结构","ex":{"en":"built on a wooden framework","cn":"建在木框架上"}},{"en":"a set of beliefs, ideas or rules that is used as the basis for making judgements, decisions, etc.","cn":"（作为判断、决定等基础的）信念，观点，准则","ex":{"en":"a theoretical/conceptual framework","cn":"理论／概念框架"}},{"en":"the structure of a particular system","cn":"（体系的）结构，机制","ex":{"en":"the basic framework of society","cn":"社会的基本结构"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"体制;体系","en":"A framework is a particular set of rules, ideas, or beliefs which you use in order to deal with problems or to decide what to do.","ex":{"en":"... within the framework of federal regulations.","cn":"在联邦法规的体制内"}},{"pos":"N-COUNT 可数名词","cn":"框架;构架;支架","en":"A framework is a structure that forms a support or frame for something.","ex":{"en":"...wooden shelves on a steel framework.","cn":"钢支架上的木隔板"}}]},"media":{"uk":"media/uk/framework__gb_1.mp3","us":"media/us/framework__us_1.mp3"},"examples":[{"en":"We need to establish a legal framework for the protection of the environment.","cn":"我们需要建立一个法律体制来保护环境。"},{"en":"The report provides a framework for further research.","cn":"报告提供了进一步研究的原则。"}]},"fresh":{"media":{"uk":"media/uk/fresh__gb_1.mp3","us":"media/us/fresh__us_1.mp3"},"oxford":{"phon":"freʃ","pos":"adjective","senses":[{"en":"recently produced or picked and not frozen, dried or preserved in tins or cans","cn":"新鲜的；新产的；刚摘的","sc":"food","ex":{"en":"Is this milk fresh?","cn":"这是鲜牛奶吗？"}},{"en":"pleasantly clean, pure or cool","cn":"清新的；凉爽的","g":"[usually before noun]","sc":"clean/cool","ex":{"en":"a toothpaste that leaves a nice fresh taste in your mouth","cn":"在口中留下舒适清凉味道的牙膏"}},{"en":"made or experienced recently","cn":"新近的；新近出现的；新近体验的","sc":"new","ex":{"en":"fresh tracks in the snow","cn":"雪地上的新脚印"}},{"en":"new or different in a way that adds to or replaces something","cn":"新的；不同的","g":"[usually before noun]","sc":"new","ex":{"en":"a fresh coat of paint","cn":"刚涂的一层油漆"}},{"en":"containing no salt","cn":"淡的；无盐的","g":"[usually before noun]","sc":"water","ex":{"en":"There is a shortage of fresh water on the island.","cn":"岛上缺少淡水。"}},{"en":"quite strong and cold","cn":"凉飕飕的","sc":"weather","ex":{"en":"a fresh breeze","cn":"凉爽的微风"}},{"en":"quite cold with some wind","cn":"清凉的；清爽的","lab":"British English","sc":"weather","ex":{"en":"It's fresh this morning, isn't it?","cn":"今天早上凉飕飕的，是不是？"}},{"en":"looking clear, bright and attractive","cn":"洁净的；明净的；亮丽的","sc":"clear/bright","ex":{"en":"He looked fresh and neat in a clean white shirt.","cn":"他穿上干净的白衬衫显得清爽利落。"}},{"en":"full of energy","cn":"精力充沛","g":"[not usually before noun]","sc":"full of energy","ex":{"en":"Regular exercise will help you feel fresher and fitter.","cn":"经常锻炼会使你感觉更加精力充沛，身体健康。"}},{"en":"having just come from a particular place; having just had a particular experience","cn":"刚从…来；刚有过…经历","sc":"just finished","ex":{"en":"students fresh out of college","cn":"刚刚毕业的大学生"}},{"en":"rude and too confident in a way that shows a lack of respect for somebody or a sexual interest in somebody","cn":"粗鲁；无礼；（对异性）放肆","g":"[not before noun]","lab":"informal","sc":"rude/confident","ex":{"en":"Don't get fresh with me!","cn":"别对我无礼！"}},{"en":"freshly","cn":"新鲜地；刚刚","ex":{"en":"fresh-baked bread","cn":"刚烤好的面包"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"新的;替代的;另外的;外加的","en":"A fresh thing or amount replaces or is added to a previous thing or amount.","ex":{"en":"He asked Strathclyde police, which carried out the original investigation, to make fresh inquiries","cn":"他要求原来负责案子的斯特拉斯克莱德警方展开新一轮的调查。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"新近的;最近的","en":"Something that is fresh has been done, made, or experienced recently.","ex":{"en":"There were no fresh car tracks or footprints in the snow","cn":"雪地里没有留下新的车辙或脚印。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)新鲜的，非冷冻的,非罐装的","en":"Fresh food has been picked or produced recently, and has not been preserved, for example by being frozen or put in a tin.","ex":{"en":"...locally caught fresh fish.","cn":"当地捕到的鲜鱼"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"新颖的;别致的;有独创性的","en":"If you describe something as fresh, you like it because it is new and exciting.","ex":{"en":"These designers are full of fresh ideas.","cn":"这些设计师满脑子都是新创意。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(外观)洁净的,亮丽的","en":"If you describe something as fresh, you mean that it is pleasant, bright, and clean in appearance.","ex":{"en":"Gingham fabrics always look fresh and pretty.","cn":"方格花布织物看上去总是鲜亮好看。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"清新的;清爽的;清凉的","en":"If something smells, tastes, or feels fresh, it is clean or cool.","ex":{"en":"The air was fresh and for a moment she felt revived.","cn":"空气清新，有那么一会儿她感到恢复了活力。"}},{"pos":"ADJ 形容词","cn":"(河流、湖泊等的水)淡的","en":"Fresh water is water that is not salty, for example the water from rivers or lakes.","ex":{"en":"Fresh water and other commodities are in short supply.","cn":"淡水和其他商品短缺。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"寒冷的;凛冽的;有风的","en":"If you say that the weather is fresh, you mean that it is fairly cold and windy.","ex":{"en":"It was a fine, fresh summer morning","cn":"那是一个晴好而清寒的夏日早晨。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(颜色)鲜艳的，明艳的","en":"Fresh colours are clear, bright, and fairly light.","ex":{"en":"...a semi-circular mosaic, its startling colours still fresh.","cn":"令人惊叹的颜色依旧鲜艳的半圆形镶嵌画"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"容光焕发的;气色好的","en":"If someone has a fresh face or complexion, their skin looks healthy.","ex":{"en":"His fresh complexion made him look younger than he was.","cn":"他的好气色令他看上去比实际年龄年轻。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精神抖擞的;精力充沛的","en":"If you feel fresh, you feel full of energy and enthusiasm.","ex":{"en":"It's vital we are as fresh as possible for those matches","cn":"尽可能保持旺盛的精力参加那几场比赛对我们来说至关重要。"}},{"pos":"ADJ 形容词","cn":"(油漆)未干的","en":"Fresh paint is not yet dry."},{"pos":"ADJ 形容词","cn":"刚从…来的;刚经历过…的","en":"If you are fresh from a particular place or experience, you have just come from that place or you have just had that experience. You can also say that someone is fresh out of a place.","ex":{"en":"I returned to the office, fresh from Heathrow","cn":"我刚从希思罗机场回到办公室。"}},{"pos":"PHRASE 短语","cn":"刚用完…的;一点儿不剩的","en":"If you are fresh out of something, you have recently used the last of it and have none left.","ex":{"en":"When I needed a tape to record an interview on I found I was fresh out of cassettes.","cn":"我想找一盘带子为访谈录音时发现磁带刚刚都用完了。"}}]},"examples":[{"en":"Regular exercise will help you feel fresher and fitter.","cn":"经常锻炼会使你感觉更加精力充沛，身体健康。"},{"en":"I managed to sleep on the plane and arrived feeling as fresh as a daisy.","cn":"我总算在飞机上睡了觉，到达时精神焕发。"}]},"fractions":{"lemma":"fraction"},"fraction":{"oxford":{"phon":"ˈfrækʃn","pos":"noun","senses":[{"en":"a small part or amount of something","cn":"小部分；少量；一点儿","lab":"British English","ex":{"en":"Only a small fraction of a bank's total deposits will be withdrawn at any one time.","cn":"任何时候，一家银行的总存款只有少量会被提取。"}},{"en":"a division of a number, for example ⅝","cn":"分数；小数","ex":{"en":"How do you express 25% as a fraction?","cn":"25%用小数怎么表示？"}},{"en":"a quantity of liquid that has been collected as a result of a process that separates the parts of a liquid mixture","cn":"分数：由于分离液体混合物各部分的过程而收集的一定数量的液体","lab":"chemistry","ex":{"en":"The third fraction contains alcohols with boiling points of 120–130℃.","cn":"第三馏分含有沸点为120-130℃的醇。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"少量;小份;一点儿","en":"A fraction of something is a tiny amount or proportion of it.","ex":{"en":"She hesitated for a fraction of a second before responding","cn":"她在回答之前犹豫了一下。"}},{"pos":"N-COUNT 可数名词","cn":"分数","en":"A fraction is a number that can be expressed as a proportion of two whole numbers. For example, ½ and ⅓ are both fractions.","ex":{"en":"The students had a grasp of decimals, percentages and fractions.","cn":"学生们掌握了小数、百分数和分数。"}}]},"media":{"uk":"media/uk/fraction__gb_1.mp3","us":"media/us/fraction__us_1.mp3"},"examples":[{"en":"Only a small fraction of a bank's total deposits will be withdrawn at any one time.","cn":"任何时候，一家银行的总存款只有少量会被提取。"},{"en":"She hesitated for the merest fraction of a second.","cn":"她略微犹豫了一下。"}]},"frying":{"lemma":"fry"},"frontiers":{"lemma":"frontier"},"fronds":{"oxford":{"phon":"frɒnd","pos":"noun","senses":[{"en":"a long leaf of some plants or trees, especially palms or ferns. Fronds are often divided into parts along the edge. （","cn":"尤指棕榈类或蕨类的）叶；蕨叶"},{"en":"a long piece of seaweed that looks like one of these leaves （","cn":"海藻长条形的）植物体，叶状体"}]}},"friendliest":{"lemma":"friendly"},"frescos":{"oxford":{"phon":"ˈfreskəʊ","pos":"noun","senses":[{"en":"a picture that is painted on a wall while the plaster is still wet; the method of painting in this way","cn":"湿壁画（墙壁灰泥未干时绘）；湿壁画技法"}]}},"fragrances":{"lemma":"fragrance"},"frees":{"lemma":"free"},"fragments":{"oxford":{"phon":"ˈfræɡmənt","pos":"noun","senses":[{"en":"a small part of sth that has broken off or comes from sth larger","cn":"碎片；片段"},{"en":"to break or make sth break into small pieces or parts （","cn":"使）碎裂，破裂，分裂"}]}},"friends":{"oxford":{"phon":"frendz","pos":"","senses":[{"en":"a popular US television comedy series (1994-2004) about six close friends in New York. The characters are Monica, Rachel, Phoebe, Chandler, Ross and Joey. The stories are about the joys and problems of love, work and friendships. “How you doin'?”Joey in Friends","cn":"朋友：美国受欢迎的电视喜剧系列（1994-2004年），讲述六个纽约的亲密朋友。角色是莫妮卡，瑞秋，菲比，钱德勒，罗斯和乔伊。这些故事是关于爱情，工作和友谊的快乐和问题。"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld5_friends.mp3","us":"media/ldoce/hwd/ame/6/ld5_friends.mp3"},"base":"friend"},"fruits":{"lemma":"fruit"},"friendlier":{"lemma":"friendly"},"freshmen":{"lemma":"freshman"},"frills":{"oxford":{"phon":"frɪl","pos":"noun","senses":[{"en":"a narrow strip of cloth with a lot of folds that is attached to the edge of a dress, curtain, etc. to decorate it （","cn":"衣服、窗帘等的）饰边，褶边，荷叶边"},{"en":"things that are not necessary but are added to make sth more attractive or interesting","cn":"不实用的装饰；虚饰"}]}},"frosty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"霜冻的;严寒的","en":"If the weather is frosty, the temperature is below freezing.","ex":{"en":"...sharp, frosty nights.","cn":"寒冷刺骨的夜晚"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"结霜的;被霜覆盖的","en":"You describe the ground or an object as frosty when it is covered with frost.","ex":{"en":"The street was deserted except for a cat lifting its paws off the frosty stones.","cn":"街上空无一人，只有一只猫在结霜的石砖上拾爪而行。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷淡的;冷若冰霜的","en":"If you describe someone's behaviour as frosty, you think it is unfriendly.","ex":{"en":"The president may get a frosty reception in New Hampshire","cn":"总统在新罕布什尔州可能会受到冷遇。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used especially when you feel uncomfortable","cn":""},{"en":"a little cold, often in a way that feels comfortable","cn":""},{"en":"a little cold, but not very cold, in a way that feels rather uncomfortable","cn":""}]},"collocations":{"phrases":["VERBS be, look | become, get, turn when the weather turns frosty | remain, stay","ADV. very","PHRASES cold and frosty The day dawned cold and frosty. 2 unfriendly","VERBS be, look, seem | become, turn He cool green eyes became positively frosty. | remain","ADV. decidedly, distinctly, positively, very The atmosphere in the room was decidedly frosty. | pretty"]},"media":{"uk":"media/ldoce/hwd/bre/5/frosty0205.mp3","us":"media/ldoce/hwd/ame/6/frosty.mp3"},"examples":[{"en":"‘No, thank you,’ she said frostily. “","cn":"不，谢谢你。”她冷冰冰地说。"},{"en":"The latest proposals were given a frosty reception.","cn":"对最新的建议反应冷淡。"}],"oxford":{"phon":"ˈfrɒsti","pos":"adjective","senses":[{"en":"extremely cold; cold with frost","cn":"严寒的；霜冻的","ex":{"en":"a frosty morning","cn":"严寒的早晨"}},{"en":"covered with frost","cn":"结霜的","ex":{"en":"I looked out over the frosty fields.","cn":"我向外望着结霜的田野。"}},{"en":"unfriendly, in a way that suggests that somebody does not approve of something","cn":"冷淡的；冷若冰霜的","ex":{"en":"a frosty look/reply","cn":"冷冰冰的样子；冷淡的答复"}}]}},"fruitful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"富有成效的;有收获的","en":"Something that is fruitful produces good and useful results.","ex":{"en":"We had a long, happy, fruitful relationship","cn":"我们有过一段长久、愉快、双方都获益良多的关系。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(土地)丰产的，富饶的;(树木)果实结得多的","en":"Fruitful land or trees produce a lot of crops.","ex":{"en":"...a landscape that was fruitful and lush.","cn":"硕果累累、草木繁盛的景观"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something that you plan to do or try to do succeeds , you get the result that you hoped for","cn":""},{"en":"if something that you plan to do or try to do is successful you get the result that you hoped for","cn":""},{"en":"if a plan or method works , it produces the result that you want","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When something is fruitful , it's productive — but you don't have to produce fruit in order to be fruitful . You could have a fruitful trip to the mall if you come home with a slew of snappy new outfits."}]},"collocations":{"phrases":["VERBS be, prove","ADV. enormously, extremely, remarkably, very | quite, reasonably | potentially","PREP. in This research has been enormously fruitful in helping our understanding of the disease."]},"media":{"uk":"media/ldoce/hwd/bre/1/fruitful0205.mp3","us":"media/ldoce/hwd/ame/7/fruitful.mp3"},"examples":[{"en":"a fruitful collaboration/discussion","cn":"富有成效的合作/讨论"},{"en":"Today’s meeting proved more fruitful than last week’s.","cn":"事实证明今天的会议比上星期的更有成效。"}],"oxford":{"phon":"ˈfruːtfl","pos":"adjective","senses":[{"en":"producing many useful results","cn":"成果丰硕的；富有成效的","ex":{"en":"a fruitful collaboration/discussion","cn":"富有成效的合作／讨论"}},{"en":"producing a lot of crops","cn":"富饶的；丰产的","lab":"literary"}]}},"frenzy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"狂热;狂乱;疯狂","en":"Frenzy or a frenzy is great excitement or wild behaviour that often results from losing control of your feelings.","ex":{"en":"'Get out!' she ordered in a frenzy","cn":"“滚出去!”她狂怒地命令道。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, especially a child, who is overexcited has become too excited to behave calmly","cn":""},{"en":"unable to stop shouting, crying etc because you are extremely excited","cn":""},{"en":"in a state of great and uncontrollable excitement","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"In a frenzy , people go into a state of hysteria. Stay away from hungry sharks or kids at a 16th birthday party when the pizza arrives if you don't want to get caught up in a feeding frenzy ."}]},"collocations":{"phrases":["ADJ. erotic | feeding The smell of blood sent the sharks into a feeding frenzy.","VERB + FRENZY drive sb/sth into, send sb/sth into, throw sb/sth into, whip sb/sth (up) into, work sb/sth into He was so angry that he worked","PREP. in a/your ~ She tore the letter open in a frenzy.","PHRASES a frenzy of activity, in a frenzy of excitement/rage/violence"]},"media":{"uk":"media/ldoce/hwd/bre/7/frenzy0205.mp3","us":"media/ldoce/hwd/ame/4/frenzy.mp3"},"examples":[{"en":"The speaker worked the crowd up into a frenzy.","cn":"演讲者把听众煽动得疯狂起来。"},{"en":"in a frenzy of activity/excitement/violence","cn":"疯狂的活动/兴奋/暴力"}],"oxford":{"phon":"ˈfrenzi","pos":"noun","senses":[{"en":"a state of great activity and strong emotion that is often violent or frightening and not under control","cn":"疯狂；狂乱；狂暴","ex":{"en":"in a frenzy of activity/excitement/violence","cn":"疯狂的活动／兴奋／暴力"}}]}},"fruitless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无结果的;无成效的;徒劳的","en":"Fruitless actions, events, or efforts do not achieve anything at all.","ex":{"en":"It was a fruitless search","cn":"搜寻工作毫无结果。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a plan or attempt fails , it does not achieve what you want it to achieve","cn":""},{"en":"when a plan or attempt fails","cn":""},{"en":"to fail","cn":""}]},"collocations":{"phrases":["VERBS be, prove, seem | render sth Dunbar's departure rendered the whole operation quite fruitless.","ADV. quite, utterly | largely | apparently"]},"media":{"uk":"media/ldoce/hwd/bre/c/fruitless0205.mp3","us":"media/ldoce/hwd/ame/8/fruitless.mp3"},"examples":[{"en":"Our efforts to persuade her proved fruitless.","cn":"我们努力说服她，但毫无成效。"},{"en":"a fruitless attempt/search","cn":"徒然的尝试/搜查"}],"oxford":{"phon":"ˈfruːtləs","pos":"adjective","senses":[{"en":"producing no useful results","cn":"没有成果的；无成效的；徒然的","ex":{"en":"a fruitless attempt/search","cn":"徒然的尝试／搜查"}}]}},"fry":{"collins":{"senses":[{"pos":"VERB 动词","cn":"油煎;油炸;油炒","en":"When you fry food, you cook it in a pan that contains hot fat or oil. →see usage note at:","ex":{"en":"Fry the breadcrumbs until golden brown.","cn":"把面包屑炸成金褐色为止。"}},{"pos":"N-PLURAL 复数名词","cn":"鱼苗;鱼秧","en":"Fry are very small, young fish."},{"pos":"N-PLURAL 复数名词","cn":"fries 同 French fries","en":"Fries are the same as French fries."},{"pos":"PHRASAL VERB 短语动词","cn":"(尤指为尽快做好便饭)煎一下，炸一下","en":"If you fry up food, you fry it, especially in order to make a quick, casual meal.","ex":{"en":"I fried up the beef","cn":"我把牛肉煎了一下。"}},{"pos":"","cn":"","en":"相关词组：fry up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cook things such as bread or cakes in an oven","cn":""},{"en":"to cook meat or vegetables in an oven","cn":""},{"en":"to cook food in hot oil","cn":""}]},"collocations":{"phrases":["ADV. gently, lightly","PREP. in Fry the vegetables gently in oil."]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdefry.mp3","us":"media/ldoce/hwd/ame/4/fry.mp3","img":["media/thumb/fry.jpg"]},"examples":[{"en":"You'll fry on the beach if you're not careful.","cn":"你在海滩上若不小心会被太阳灼伤的。"},{"en":"Would you like ketchup with your fries?","cn":"你吃炸薯条要番茄酱吗？"}],"oxford":{"phon":"fraɪ","pos":"verb","senses":[{"en":"to cook something in hot fat or oil; to be cooked in hot fat or oil","cn":"油炸；油煎；油炒","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"fried fish","cn":"炸鱼"}},{"en":"to be burnt by the sun","cn":"（被阳光）灼伤，晒伤","g":"[intransitive]","lab":"informal","ex":{"en":"You'll fry on the beach if you're not careful.","cn":"你在海滩上若不小心会被太阳灼伤的。"}},{"en":"very small young fish","cn":"鱼苗；鱼秧子","g":"[plural]","pos":"noun"},{"en":"a long thin piece of potato fried in oil or fat","cn":"油炸土豆条；炸薯条","g":"[countable]","lab":"both especially North American English","ex":{"en":"Would you like ketchup with your fries?","cn":"你吃炸薯条要番茄酱吗？"},"pos":"noun"}]}},"fruition":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"实现;完成;取得成果","en":"If something comes to fruition, it starts to succeed and produce the results that were intended or hoped for.","ex":{"en":"These plans take time to come to fruition","cn":"这些方案需要时间才能取得成果。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a plan, project etc comes to fruition, it is successfully put into action and completed, often after a long process 〔","cn":"计划﹑项目等的〕实现﹐完成"},{"en":"come to/bring to/reach fruition His proposals only came to fruition after the war.","cn":"他的提议直到战后才得以实现。 Many people have worked together to bring this scheme to fruition. 在许多人的共同努力下﹐这一计划得以实现。"}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"An idea that is made real, such as a plan or an apple, has come to fruition ."}]},"collocations":{"phrases":["ADJ. full","VERB + FRUITION come to, reach Their efforts came to fruition many years later. | bring sth to It was left to her successor to bring the pla"]},"media":{"uk":"media/ldoce/hwd/bre/c/fruition0205.mp3","us":"media/ldoce/hwd/ame/c/fruition.mp3"},"examples":[{"en":"After months of hard work, our plans finally came to fruition.","cn":"经过几个月的艰苦工作，我们的计划终于完成了。"},{"en":"His extravagant ideas were never brought to fruition.","cn":"他不切实际的想法永远没有实现。"}],"oxford":{"phon":"fruˈɪʃn","pos":"noun","senses":[{"en":"the successful result of a plan, a process or an activity","cn":"（计划、过程或活动的）完成，实现，取得成果","ex":{"en":"After months of hard work, our plans finally came to fruition.","cn":"经过几个月的艰苦工作，我们的计划终于完成了。"}}]}},"friction":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"矛盾;不和;争执","en":"If there is friction between people, there is disagreement and argument between them.","ex":{"en":"Sara sensed that there had been friction between her children","cn":"萨拉感觉到她的孩子之间有过争执。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"摩擦力","en":"Friction is the force that makes it difficult for things to move freely when they are touching each other.","ex":{"en":"The pistons are graphite-coated to reduce friction.","cn":"活塞上涂了一层石墨以减小摩擦力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"摩擦","en":"Friction is the rubbing of one object against another.","ex":{"en":"...the friction of his leg against hers.","cn":"他和她的腿之间的擦蹭"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when people disagree with each other","cn":""},{"en":"when people are unable to agree, especially about something important - use this as a way of avoiding more direct words like 'argument' and 'disagreement'","cn":""},{"en":"a serious disagreement about a decision, plan, or action, that causes arguments for a long time in newspapers, on television etc","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"When one thing rubs and grates against another, it causes friction . That can include two clashing personalities or simply a match striking the matchbox and causing a spark."}]},"collocations":{"phrases":["ADJ. considerable, serious | increasing | constant I'm exhausted from the constant friction between my boss and my colleagues.","VERB + FRICTION cause, create, generate, lead to, produce His decision led to considerable friction in his family. | prevent","PREP. ~ between friction between neighbours | ~ with Her requests for time off created friction with her boss.","PHRASES a cause/source of friction 2 rubbing of one thing against another","VERB + FRICTION cause, generate, produce Rubbing the stones together produces friction. | reduce"]},"media":{"uk":"media/ldoce/hwd/bre/5/friction0205.mp3","us":"media/ldoce/hwd/ame/4/friction.mp3"},"examples":[{"en":"The force of friction slows the spacecraft down as it re-enters the earth's atmosphere.","cn":"太空船重返地球大气层时因有摩擦力而减慢速度。"},{"en":"Friction between moving parts had caused the engine to overheat.","cn":"活动部件的摩擦使发动机过热。"}],"oxford":{"phon":"ˈfrɪkʃn","pos":"noun","senses":[{"en":"the action of one object or surface moving against another","cn":"摩擦","g":"[uncountable]","ex":{"en":"Friction between moving parts had caused the engine to overheat.","cn":"活动部件的摩擦使发动机过热。"}},{"en":"the resistance (= the force that stops something moving) of one surface to another surface or substance moving over or through it","cn":"摩擦力","g":"[uncountable]","lab":"physics","ex":{"en":"The force of friction slows the spacecraft down as it re-enters the earth's atmosphere.","cn":"航天飞船重返地球大气层时因有摩擦力而减慢速度。"}},{"en":"a lack of friendship or agreement among people who have different opinions about something","cn":"争执；分歧；不和","g":"[uncountable, countable]","ex":{"en":"conflicts and frictions that have still to be resolved","cn":"仍有待解决的冲突和摩擦"}}]}},"frailty":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"弱点;脆弱","en":"If you refer to the frailties or frailty of people, you are referring to their weaknesses.","ex":{"en":"...the frailties of human nature.","cn":"人性的弱点"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(体质的)虚弱","en":"Frailty is the condition of having poor health.","ex":{"en":"She died after a long period of increasing frailty.","cn":"在很长一段时间里，她身体日渐虚弱，最后离开人世。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the lack of strength or health","cn":"脆弱﹐虚弱"},{"en":"something bad or weak in your character 〔","cn":"性格上的〕弱点﹐缺点"}]},"vocab":{"pos":"n","senses":[{"en":"Frailty describes a quality that's shared by a sick kitten, an elderly man, and a shoddily built go cart. They all have a delicate weakness or vulnerability and seem to require some kind of care."}]},"collocations":{"phrases":["ADJ. increasing Despite increasing physical frailty, he continued to write stories. | human a figure of authority, but one all too prone to "]},"media":{"uk":"media/ldoce/hwd/bre/f/frailty0205.mp3","us":"media/ldoce/hwd/ame/5/frailty.mp3"},"examples":[{"en":"Increasing frailty meant that she was more and more confined to bed.","cn":"日益衰弱意味着她愈来愈需要卧床。"},{"en":"the frailties of human nature","cn":"人性的种种弱点"}],"oxford":{"phon":"ˈfreɪlti","pos":"noun","senses":[{"en":"weakness and poor health","cn":"虚弱；衰弱","g":"[uncountable]","ex":{"en":"Increasing frailty meant that she was more and more confined to bed.","cn":"日益衰弱意味着她愈来愈需要卧床。"}},{"en":"weakness in a person’s character or moral standards","cn":"（性格或道德上的）弱点，懦弱，软弱","g":"[uncountable, countable]","lab":"formal","ex":{"en":"human frailty","cn":"人性的弱点"}}]}},"fraud":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"诈骗;欺诈","en":"Fraud is the crime of gaining money or financial benefits by a trick or by lying.","ex":{"en":"He was jailed for two years for fraud and deception","cn":"他因为诈骗和欺诈入狱服刑两年。"}},{"pos":"N-COUNT 可数名词","cn":"骗子;诈骗者;骗人的东西","en":"A fraud is something or someone that deceives people in a way that is illegal or dishonest.","ex":{"en":"Unfortunately the portraits were frauds","cn":"不幸的是这些肖像都是骗人的。"}},{"pos":"N-COUNT 可数名词","cn":"骗子;假货;赝品","en":"If you call someone or something a fraud, you are criticizing them because you think that they are not genuine, or are less good than they claim or appear to be.","ex":{"en":"...all those fashion frauds who think they are being original by raiding the tired old styles of the '60s.","cn":"所有那些抄袭 60 年代的过时风格却自认为具有原创性的时尚造假者"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of stealing from a bank, shop etc","cn":""},{"en":"the crime of breaking into someone’s home in order to steal things","cn":""},{"en":"the crime of stealing something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A fraud is a something that deceives or tricks another person, usually to get their money. Frauds are dishonest."}]},"collocations":{"phrases":["ADJ. serious | massive | complex, sophisticated | attempted | alleged | computer A bank lost several million pounds through a sophisticated ","FRAUD + NOUN squad detectives from the fraud squad • Note at CRIME (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/9/fraud0205.mp3","us":"media/ldoce/hwd/ame/9/fraud.mp3"},"examples":[{"en":"She felt a fraud accepting their sympathy (= because she was not really sad).","cn":"她接受他们的同情时感到自己是在骗人。"},{"en":"He's nothing but a liar and a fraud.","cn":"他只不过是个撒谎者和骗子。"}],"oxford":{"phon":"frɔːd","pos":"noun","senses":[{"en":"the crime of cheating somebody in order to get money or goods illegally","cn":"欺诈罪；欺骗罪","g":"[uncountable, countable]","lab":"British English","ex":{"en":"She was charged with credit card fraud.","cn":"她被控告信用卡诈骗罪。"}},{"en":"a person who pretends to have qualities, abilities, etc. that they do not really have in order to cheat other people","cn":"骗子；行骗的人","g":"[countable]","ex":{"en":"He's nothing but a liar and a fraud.","cn":"他只不过是个撒谎者和骗子。"}},{"en":"something that is not as good, useful, etc. as people claim it is","cn":"伪劣品；冒牌货","g":"[countable]"}]}},"freezer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冰柜;冷冻室","en":"A freezer is a large container like a fridge in which the temperature is kept below freezing point so that you can store food inside it for long periods."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large piece of electrical kitchen equipment in which food can be stored at very low temperatures for a long time","cn":"冷藏箱﹐冷冻柜﹐冰柜"},{"en":"a part of a fridge in which food can be stored at very low temperatures for a long time 〔","cn":"冰箱中的〕冷冻室"}]},"collocations":{"phrases":["ADJ. domestic | fridge | chest | deep","VERB + FREEZER fill, stock | defrost","FREEZER + NOUN cabinet, compartment | bag, container | centre They bought all their frozen food from the same freezer centre. | contents You"]},"media":{"uk":"media/ldoce/hwd/bre/8/freezer0205.mp3","us":"media/ldoce/hwd/ame/8/freezer.mp3"},"oxford":{"phon":"ˈfriːzə(r)","pos":"noun","senses":[{"en":"a large piece of electrical equipment in which you can store food for a long time at a low temperature so that it stays frozen","cn":"冷冻柜；冰柜","ex":{"en":"Your freezer contents can be insured against loss.","cn":"你的冷冻物品可以投保避免损失。"}}]}},"fragrance":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"香味;香气;芳香","en":"A fragrance is a pleasant or sweet smell.","ex":{"en":"...a shrubby plant with a strong characteristic fragrance.","cn":"散发出一种浓郁的独特香味的灌木"}},{"pos":"N-MASS 物质名词","cn":"香水","en":"Fragrance is a pleasant-smelling liquid which people put on their bodies to make themselves smell nice.","ex":{"en":"The advertisement is for a male fragrance.","cn":"这则广告宣传的是一款男士香水。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you can recognize by breathing in through your nose","cn":""},{"en":"something that you smell for a short time","cn":""},{"en":"a smell – used especially about the pleasant smell from flowers, plants, or fruit. Also used about the smell left by an animal","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A fragrance is a smell, usually a pleasant or sweet smell. Often perfumes are called fragrances ."}]},"collocations":{"phrases":["ADJ. exquisite, fresh, pleasant, sweet | delicate, faint, gentle, light, soft, subtle | floral","VERB + FRAGRANCE have This perfume has a light, fresh fragrance. | smell","FRAGRANCE + VERB fill sth The fragrance of lavender filled the room. | be reminiscent of sth Geranium oil has a sweet fragrance reminiscent ","PHRASES full of fragrance fruits full of exquisite fragrance and flavour"]},"media":{"uk":"media/ldoce/hwd/bre/b/fragrance0205.mp3","us":"media/ldoce/hwd/ame/c/fragrance.mp3"},"examples":[{"en":"an exciting new fragrance from Dior","cn":"迪奥新推出的一款令人惊喜的香水"},{"en":"The bath oil comes in various fragrances.","cn":"这种沐浴油有不同的香味。"}],"oxford":{"phon":"ˈfreɪɡrəns","pos":"noun","senses":[{"en":"a pleasant smell","cn":"香气；香味；芳香","g":"[countable, uncountable]","ex":{"en":"The bath oil comes in various fragrances.","cn":"这种沐浴油有不同的香味。"}},{"en":"a liquid that you put on your skin in order to make yourself smell nice","cn":"香水","g":"[countable]","ex":{"en":"an exciting new fragrance from Dior","cn":"迪奥新推出的一款令人惊喜的香水"}}]}},"freeze":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)冻结;(使)结冰;(使)凝固","en":"If a liquid or a substance containing a liquid freezes, or if something freezes it, it becomes solid because of low temperatures.","ex":{"en":"If the temperature drops below 0°C, water freezes","cn":"温度降到零摄氏度以下水就会结冰。"}},{"pos":"V-ERG 及物/不及物动词","cn":"冷冻(食物等)","en":"If you freeze something such as food, you preserve it by storing it at a temperature below freezing point. You can also talk about how well food freezes .","ex":{"en":"You can freeze the soup at this stage","cn":"这时可以把汤冷冻起来。"}},{"pos":"VERB 动词","cn":"(管子、机器等因液体结冰)冻得堵塞，冻牢","en":"If something such as a pipe or machine freezes, it becomes blocked or stiff with ice or frozen liquid.","ex":{"en":"The water pipes will freeze.","cn":"水管会冻住。"}},{"pos":"VERB 动词","cn":"(天气)冷到结冰的程度，冰冻","en":"When it freezes outside, the temperature falls below freezing point.","ex":{"en":"What if it rained and then froze all through those months?","cn":"要是那几个月一直又下雨又冰冻怎么办？"}},{"pos":"VERB 动词","cn":"冻僵;感到极冷","en":"If you freeze, you feel extremely cold.","ex":{"en":"The windows didn't fit at the bottom so for a while we froze even in the middle of summer","cn":"窗子底下关不严，所以有一段时间即使是在盛夏我们也觉得很冷。"}},{"pos":"VERB 动词","cn":"僵住;呆住;停住不动","en":"If someone who is moving freezes, they suddenly stop and become completely still and quiet.","ex":{"en":"She froze when the beam of the flashlight struck her.","cn":"当手电筒的光照到她身上时她僵住了。"}},{"pos":"VERB 动词","cn":"冻结，限定(物价、工资等)","en":"If the government or a company freeze things such as prices or wages, they state officially that they will not allow them to increase for a fixed period of time.","ex":{"en":"They want the government to freeze prices","cn":"他们希望政府冻结物价。"}},{"pos":"VERB 动词","cn":"冻结，暂停(计划、进程等)","en":"If a government freezes a plan or process, they state officially that they will not allow it to continue for a period of time.","ex":{"en":"Britain has already frozen its aid programme","cn":"英国已冻结了其援助项目。"}},{"pos":"VERB 动词","cn":"冻结，查封(银行账户、基金、财产等)","en":"If someone in authority freezes something such as a bank account, fund, or property, they obtain a legal order which states that it cannot be used or sold for a particular period of time.","ex":{"en":"The governor's action freezes 300,000 accounts","cn":"州长采取的行动冻结了 30 万个账户。"}},{"pos":"PHRASAL VERB 短语动词","cn":"排挤;逐出;挤对","en":"If you freeze someone out of an activity or situation, you prevent them from being involved in it by creating difficulties or by being unfriendly.","ex":{"en":"Other traders did everything they could to freeze us out of the business.","cn":"其他商人则想方设法地要把我们排挤出这个生意圈。"}},{"pos":"PHRASAL VERB 短语动词","cn":"(表面)封冻，结冰","en":"If something freezes over, it becomes covered with a layer of ice or other frozen substance.","ex":{"en":"The air temperature was well below freezing, and lakes and rivers froze over","cn":"气温远远低于零度，湖面和河面都封冻了。"}},{"pos":"PHRASAL VERB-ERG","cn":"(使)完全被冰覆盖(或堵塞)","en":"If something freezes up or if something freezes it up, it becomes completely covered or blocked with ice.","ex":{"en":"...lavatories that often freeze up in winter","cn":"在冬季经常完全冻住的抽水马桶"}},{"pos":"","cn":"","en":"相关词组：freeze out freeze over freeze up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make food cold when it has been hot or warm","cn":""},{"en":"to make food or drink very cold, without freezing it","cn":""},{"en":"to make something extremely cold so that it freezes, in order to preserve it for a long time","cn":""}]},"collocations":{"phrases":["ADV. solid The pond had frozen solid. | over, up The lake has frozen over. The pipes have frozen up.","PHRASES freeze to death Hundreds of homeless people could freeze to death this winter. 2 preserve food","ADV. well Many vegetables freeze very well. 3 stop moving","ADV. suddenly | for a moment/second, momentarily His smile froze for a moment.","VERB + FREEZE seem to Suddenly, Ronny seemed to freeze.","PREP. in/with She froze with horror when she saw the body. | into Maggie's face had frozen into a cold mask.","PHRASES freeze to the spot He was so surprised he froze to the spot. 4 wages/prices","ADV. effectively Wages were effectively frozen for six months."]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdefreeze.mp3","us":"media/ldoce/hwd/ame/a/freeze1.mp3"},"examples":[{"en":"The police officer shouted ‘Freeze!’ and the man dropped the gun.","cn":"警察大喊“不准动！”那个男人便放下了枪。"},{"en":"Farmers still talk about the big freeze of '99.","cn":"农民至今还在谈论 1999 年的大严寒。"}],"oxford":{"phon":"friːz","pos":"verb","senses":[{"en":"to become hard, and often turn to ice, as a result of extreme cold; to make something do this","cn":"（使）冻结，结冰","g":"[intransitive, transitive]","sc":"become ice","ex":{"en":"Water freezes at 0°C.","cn":"水在 0 摄氏度时结冰。"}},{"en":"if a pipe, lock or machine freezes, or something freezes it, it becomes blocked with frozen liquid and therefore cannot be used","cn":"（使）冻住，冻堵","g":"[intransitive, transitive]","sc":"of pipe/lock/machine","ex":{"en":"The pipes have frozen, so we've got no water.","cn":"水管已经冻了，我们接不到水。"}},{"en":"when it freezes, the weather is at or below 0° Celsius","cn":"冰冻；严寒","g":"[intransitive]","sc":"of weather","ex":{"en":"It may freeze tonight, so bring those plants inside.","cn":"今夜可能有霜冻，把花草搬进屋来吧。"}},{"en":"to be very cold; to be so cold that you die","cn":"感觉很冷；（使）冻死","g":"[intransitive, transitive]","sc":"be very cold","ex":{"en":"Every time she opens the window we all freeze.","cn":"每次她开窗户，我们都冷得要死。"}},{"en":"to keep something, especially food, at a very low temperature in order to preserve it","cn":"（尤指将食物）冷冻贮藏，冷藏","g":"[transitive]","sc":"food","ex":{"en":"Can you freeze this cake?","cn":"你能不能把这个蛋糕冷藏起来？"}},{"en":"to be able to be kept at a very low temperature","cn":"能冷冻贮藏","g":"[intransitive]","sc":"food","ex":{"en":"Some fruits freeze better than others.","cn":"有些水果比其他的更适宜冷藏。"}},{"en":"to stop moving suddenly because of fear, etc.","cn":"（因害怕等）停住不动；惊呆；吓呆","g":"[intransitive]","lab":"figurative","sc":"stop moving","ex":{"en":"I froze with terror as the door slowly opened.","cn":"门慢慢开启时我吓呆了。"}},{"en":"when a computer screen freezes, you cannot move any of the images, etc. on it, because there is a problem with the system","cn":"（屏幕）冻结","g":"[intransitive]","sc":"computer"},{"en":"to stop a film or video in order to look at a particular picture","cn":"使定格","g":"[transitive]","sc":"film/movie","ex":{"en":"Freeze the action there!","cn":"把这个画面定格在那里！"}},{"en":"to hold wages, prices, etc. at a fixed level for a period of time","cn":"使固定不动","g":"[transitive]","sc":"wages/prices","ex":{"en":"Salaries have been frozen for the current year.","cn":"今年的工资已冻结。"}},{"en":"to prevent money, a bank account, etc. from being used by getting a court order which bans it","cn":"冻结（资金、银行账户等）","g":"[transitive]","sc":"money/bank account","ex":{"en":"The company's assets have been frozen.","cn":"这家公司的资产已被冻结。"}},{"en":"the act of keeping wages, prices, etc. at a particular level for a period of time","cn":"冻结","sc":"of wages/prices","ex":{"en":"a wage/price freeze","cn":"工资／物价的冻结"},"pos":"noun"},{"en":"the act of stopping something","cn":"停止","g":"[usually singular]","sc":"stopping something","ex":{"en":"a freeze on imports","cn":"停止进口"},"pos":"noun"},{"en":"an unusually cold period of weather during which temperatures stay below 0° Celsius","cn":"冰冻期；严寒期","g":"[usually singular]","lab":"British English","sc":"cold weather","ex":{"en":"Farmers still talk about the big freeze of '99.","cn":"农民至今还在谈论 1999 年的大严寒。"},"pos":"noun"},{"en":"a short period of time, especially at night, when the temperature is below 0° Celsius","cn":"霜冻","lab":"North American English","sc":"cold weather","ex":{"en":"A freeze warning was posted for Thursday night.","cn":"据警报星期四夜间有霜冻。"},"pos":"noun"}]}},"frog":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蛙;蛙类动物","en":"A frog is a small creature with smooth skin, big eyes, and long back legs which it uses for jumping. Frogs usually live near water."},{"pos":"N-COUNT 可数名词","cn":"法国佬(可能具冒犯意味)","en":"Frogs is sometimes used to refer to French people. This use could cause offence."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small green animal that lives near water and has long legs for jumping","cn":"蛙﹐青蛙"},{"en":"to have difficulty in speaking, especially because of a sore throat 〔","cn":"尤因喉咙痛〕说话困难"},{"en":"a very offensive word for someone from France. Do not use this word.","cn":"法国佬"}]},"collocations":{"phrases":["FROG + VERB hop, jump, leap, plop into sth The frog plopped into the pond. | croak","FROG + NOUN spawn (also frogspawn)"]},"media":{"img":["media/ldoce/img/frog.jpg","media/thumb/frog.jpg"],"uk":"media/ldoce/hwd/bre/e/frog0205.mp3","us":"media/ldoce/hwd/ame/e/frog1.mp3"},"examples":[{"en":"the croaking of frogs","cn":"蛙鸣"}],"oxford":{"phon":"frɒɡ","pos":"noun","senses":[{"en":"a small animal with smooth skin, that lives both on land and in water (= is an amphibian). Frogs have very long back legs for jumping, and no tail.","cn":"蛙；青蛙","ex":{"en":"the croaking of frogs","cn":"蛙鸣"}},{"en":"an offensive word for a French person","cn":"法国佬（对法国人的蔑称）","lab":"taboo, offensive, slang，，，，"}]}},"frail":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"虚弱的;体弱的","en":"Someone who is frail is not very strong or healthy.","ex":{"en":"She lay in bed looking particularly frail.","cn":"她躺在床上，看上去特别虚弱。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易碎的;易坏的","en":"Something that is frail is easily broken or damaged.","ex":{"en":"The frail craft rocked as he clambered in.","cn":"他爬进来的时候，那件易碎的工艺品摇晃起来。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not physically strong, sometimes because you are ill","cn":""},{"en":"weak and thin, especially because you are old","cn":""},{"en":"feeling weak in your legs and only able to walk slowly and unsteadily","cn":""}]},"vocab":{"pos":"1 adj 2 n","senses":[{"en":"Something that is delicate and fragile can be described as frail . Grandma's favorite vase is probably too frail to use for football practice; some of us have learned that the hard way."}]},"collocations":{"phrases":["VERBS be, look, seem | become, get, grow","ADV. extremely, very | increasingly | rather | mentally, physically Many old people become mentally frail.","PHRASES old and frail She looked old and frail."]},"media":{"uk":"media/ldoce/hwd/bre/5/frail0205.mp3","us":"media/ldoce/hwd/ame/1/frail.mp3"},"examples":[{"en":"Mother was becoming too frail to live alone.","cn":"母亲已逐渐衰弱到无法独居。"},{"en":"the frail stems of the flowers","cn":"柔弱的花茎"}],"oxford":{"phon":"freɪl","pos":"adjective","senses":[{"en":"physically weak and thin","cn":"瘦弱的","ex":{"en":"Mother was becoming too frail to live alone.","cn":"母亲已逐渐衰弱到无法独居。"}},{"en":"weak; easily damaged or broken","cn":"弱的；易损的；易碎的","ex":{"en":"the frail stems of the flowers","cn":"柔弱的花茎"}}]}},"freckle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指脸上的)雀斑，色斑","en":"Freckles are small light brown spots on someone's skin, especially on their face.","ex":{"en":"He had short ginger-coloured hair and freckles.","cn":"他一头姜黄色的短发，脸上有些雀斑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small area of skin that is a different colour from the rest of someone's skin","cn":""},{"en":"a small raised red mark, especially on someone's face, that appears suddenly and remains for a short time, often on young people","cn":""},{"en":"a very small, light-brown mark, usually on the face and arms, which some light-skinned people have from birth or get when they spend time in the sun","cn":""}]},"collocations":{"phrases":["ADJ. brown, dark, golden, light, pale","VERB + FRECKLE be covered with, have","PHRASES a crop/sprinkling of freckles She had wonderful clear skin with an attractive sprinkling of freckles."]},"media":{"uk":"media/ldoce/hwd/bre/3/freckle0205.mp3","us":"media/ldoce/hwd/ame/6/freckle.mp3"},"examples":[{"en":"a freckled face/schoolgirl","cn":"有雀斑的脸/女学生"}],"oxford":{"phon":"ˈfrekl","pos":"noun","senses":[{"en":"a small, pale brown spot on a person’s skin, especially on their face, that often becomes darker after time spent in the sun","cn":"雀斑；小斑点","ex":{"en":"She had wonderful clear skin with an attractive sprinkling of freckles.","cn":"她光滑的皮肤上有几处可爱的小雀斑。"}}]}},"freak":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"反常的;怪异的;极端的","en":"A freak event or action is one that is a very unusual or extreme example of its type.","ex":{"en":"Weir broke his leg in a freak accident playing golf","cn":"韦尔因为一次打高尔夫时发生的离奇事故折断了腿。"}},{"pos":"N-COUNT 可数名词","cn":"(对某事物或活动痴迷的)…狂","en":"If you describe someone as a particular kind of freak, you are emphasizing that they are very enthusiastic about a thing or activity, and often seem to think about nothing else.","ex":{"en":"Oat bran became the darling of health freaks last year.","cn":"燕麦麸在去年成为保健狂人的最爱。"}},{"pos":"N-COUNT 可数名词","cn":"怪人;怪胎","en":"People are sometimes referred to as freaks when their behaviour or attitude is very different from that of the majority of people.","ex":{"en":"However, outside of these institutions the black thinking woman is looked upon as a freak","cn":"然而，在这些机构之外，有思想的黑人女性被当作怪胎看待。"}},{"pos":"N-COUNT 可数名词","cn":"畸形(人)(可能具冒犯意味)","en":"If you refer to someone as a freak, you mean that they are physically abnormal in some way. This use could cause offence."},{"pos":"V-ERG 及物/不及物动词","cn":"(使)吃惊;(使)不安;(使)恼怒;(使)困惑","en":"If someone freaks, or if something freaks them, they suddenly feel extremely surprised, upset, angry, or confused.","ex":{"en":"I saw five cop cars pull into the driveway. And I literally freaked","cn":"我看到 5 辆警车开进了我家的车道。我简直吓坏了。"}},{"pos":"PHRASAL VERB-ERG","cn":"(使)吃惊;(使)不安;(使)恼怒;(使)困惑","en":"If someone freaks out, or if something freaks them out, they suddenly feel extremely surprised, upset, angry, or confused.","ex":{"en":"I remember the first time I went onstage. I freaked out completely","cn":"我还记得自己第一次登台的情形。我完全吓坏了。"}},{"pos":"","cn":"","en":"相关词组：freak out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who likes a particular sport, team, or famous entertainer very much","cn":""},{"en":"someone who likes a particular activity very much","cn":""},{"en":"someone who likes a subject, activity, performer etc very much, is very interested in them and knows a lot about them","cn":""}]},"vocab":{"pos":"1 n 2 v","senses":[{"en":"Freak is a not-so-nice noun that refers to either a person who expresses such an intense obsession with something that it resembles addiction, or a person or animal that is monstrous and deformed."}]},"collocations":{"phrases":["FREAK + NOUN accident, result, storm, wave A driver was killed in a freak accident when a cow fell from a bridge. The manager described the ","PREP. ~ of This was no more than a freak of history.","PHRASES by some freak of sth By some freak of fate, she won an enormous sum of money. 2 person with a very strong interest in sth","ADJ. computer, fitness, health, speed For the real speed freak, there is a 2-litre, fuel-injection version of the car. | control Her dad see","PHRASES a bit of a freak 3 sb who is considered to be strange","VERB + FREAK feel | regard sb as Other students regarded him as a freak.","PHRASES a bit of a freak I felt a bit of a freak in my strange clothes."]},"media":{"uk":"media/ldoce/hwd/bre/0/freak_adj0205.mp3","us":"media/ldoce/hwd/ame/e/freak1.mp3"},"examples":[{"en":"By some freak of fate they all escaped without injury.","cn":"由于命运之神的奇特安排，他们全都死里逃生，毫发未损。"},{"en":"My parents really freaked when they saw my hair.","cn":"我父母看见我的头发时大惊失色。"}],"oxford":{"phon":"friːk","pos":"noun","senses":[{"en":"a person with a very strong interest in a particular subject","cn":"狂热爱好者","lab":"informal","ex":{"en":"a health/fitness freak","cn":"健康/健身狂"}},{"en":"a person who is considered to be unusual because of the way they behave, look or think","cn":"（行为、外表、想法）怪异的人；怪人","lab":"disapproving","ex":{"en":"She was treated like a freak because she didn't want children.","cn":"她因为不要孩子而被当作怪人。"}},{"en":"a person, an animal, a plant or a thing that is not considered physically normal","cn":"（指人、动植物和东西）畸形","lab":"sometimes offensive","ex":{"en":"This butterfly is a freak of nature, black and white instead of blue.","cn":"这只蝴蝶畸形，黑白相间，而不是蓝色。"}},{"en":"a very unusual and unexpected event","cn":"怪异的事；不寻常的事","ex":{"en":"By some freak of fate they all escaped without injury.","cn":"由于命运之神的奇特安排，他们全都死里逃生，毫发未损。"}},{"en":"very unusual and unexpected","cn":"不正常的；怪异的","ex":{"en":"a freak accident/storm/occurrence","cn":"反常的事故／暴风雨／事件"},"pos":"adjective"},{"en":"if somebody freaks or if something freaks them, they react very strongly to something that makes them suddenly feel shocked, surprised, frightened, etc.","cn":"（使）强烈反应，震惊，畏惧","ex":{"en":"My parents really freaked when they saw my hair.","cn":"我父母看见我的头发时大惊失色。"},"pos":"verb"}]}},"friendless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没有朋友的;孤家寡人的","en":"Someone who is friendless has no friends.","ex":{"en":"The boy was unhappy because he thought he was friendless.","cn":"这个男孩自认为没有朋友，所以闷闷不乐。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having no friends and no one to help you","cn":"无朋友的﹔孤独无助的"}]},"collocations":{"phrases":["VERBS be, feel | leave sb With the departure of his remaining colleague he was left friendless.","ADV. totally, utterly | virtually"]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41friendless.mp3","us":"media/ldoce/hwd/ame/d/friendless.mp3"},"oxford":{"phon":"ˈfrendləs","pos":"adjective","senses":[{"en":"without any friends","cn":"没有朋友的","ex":{"en":"He died alone and friendless.","cn":"他孤独地死去，没有朋友。"}}]}},"franchise":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"特许经营权;专卖权;经销权","en":"A franchise is an authority that is given by an organization to someone, allowing them to sell its goods or services or to take part in an activity which the organization controls.","ex":{"en":"...fast-food franchises","cn":"快餐特许经营权"}},{"pos":"VERB 动词","cn":"出售…的特许经营权","en":"If a company franchises its business, it sells franchises to other companies, allowing them to sell its goods or services.","ex":{"en":"She has recently franchised her business","cn":"她最近向其他公司出售了公司业务的特许经营权。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指选举议会的)选举权","en":"Franchise is the right to vote in an election, especially one in which people elect a parliament.","ex":{"en":"...the introduction of universal franchise","cn":"普选权的出现"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the right to vote in an election","cn":""},{"en":"if you have a vote , you have the right to vote","cn":""},{"en":"the right to vote in elections - use this especially to talk about people's fight to be allowed to vote","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A franchise is a right granted by a government or corporation to an individual or group of individuals. One of the most important government-issued rights — so important it's known simply as \"the franchise \" — is the right to vote."}]},"collocations":{"phrases":["ADJ. democratic | universal the fight for a universal franchise | limited, restricted | parliamentary","VERB + FRANCHISE qualify for It was decided that all men in the armed forces should qualify for the franchise. | exercise He had to exercise","ADJ. catering, fast food, rail, television, etc.","VERB + FRANCHISE have, hold the company that holds the rail franchise for the south-east of the country | acquire, buy, win The company has ","FRANCHISE + NOUN system | business, company, operation | holder | agreement | auction, bid | fee","PREP. ~ for The diving school has acquired a franchise for scuba equipment.","PHRASES on a franchise basis Catering in the schools is run on a franchise basis."]},"media":{"uk":"media/ldoce/hwd/bre/6/franchise_n0205.mp3","us":"media/ldoce/hwd/ame/1/franchise1.mp3"},"examples":[{"en":"In the reorganization, Southern Television lost their franchise.","cn":"在改组过程中南方电视公司失去了特许经营权。"},{"en":"Catering has been franchised (out) to a private company.","cn":"餐饮特许经营权已授予一家私人公司。"}],"oxford":{"phon":"ˈfræntʃaɪz","pos":"noun","senses":[{"en":"formal permission given by a company to somebody who wants to sell its goods or services in a particular area; formal permission given by a government to somebody who wants to operate a public service as a business","cn":"（公司授予的）特许经销权；（国家授予的）特别经营权，特许","g":"[countable, uncountable]","lab":"North American English","ex":{"en":"a franchise agreement/company","cn":"特许经销权协议；特约代销公司"}},{"en":"a business or service run under franchise","cn":"获特许权的商业（或服务）机构","g":"[countable]","ex":{"en":"They operate franchises in London and Paris.","cn":"他们在伦敦和巴黎经营专卖店。"}},{"en":"the right to vote in a country’s elections","cn":"（公民）选举权","g":"[uncountable]","lab":"formal","ex":{"en":"universal adult franchise","cn":"成年人普选权"}},{"en":"a set of films in which the same characters appear in related stories","cn":"电影系列（一部电影衍生出一系列续集的系列电影）","g":"[countable]","ex":{"en":"Disney has successfully revived the ‘Star Wars’ franchise, with four films already released and more in the works.","cn":"迪士尼成功复兴了《星球大战》系列电影，四部电影已经上映，还有更多电影正在制作中。"}},{"en":"to give or sell a franchise to somebody","cn":"授予（或出售）特许经销权（或经营权）","ex":{"en":"Catering has been franchised (out) to a private company.","cn":"餐饮特许经营权已授予一家私人公司。"},"pos":"verb"}]}},"fridge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(电)冰箱;冷藏室","en":"A fridge is a large metal container which is kept cool, usually by electricity, so that food that is put in it stays fresh."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large piece of electrical kitchen equipment, used for keeping food and drinks cool","cn":"冰箱﹐冰柜"}]},"collocations":{"phrases":["ADJ. domestic","VERB + FRIDGE raid The kids tend to raid the fridge when they get home from school. | fill, stock The fridge was stocked with food and drink","FRIDGE + NOUN freezer | door"]},"media":{"img":["media/ldoce/img/fridge.jpg"],"uk":"media/ldoce/hwd/bre/f/fridge0205.mp3","us":"media/ldoce/hwd/ame/3/fridge.mp3"},"examples":[{"en":"This dessert can be served straight from the fridge.","cn":"这种甜食从冰箱里拿出来就可以吃。"}],"oxford":{"phon":"frɪdʒ","pos":"noun","senses":[{"en":"a piece of electrical equipment in which food is kept cold so that it stays fresh","cn":"冰箱","ex":{"en":"The kids tend to raid the fridge when they get home from school.","cn":"孩子们放学回家往往就会扫盪冰箱。"}}]}},"fragrant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"气味芬芳的;芳香的","en":"Something that is fragrant has a pleasant, sweet smell.","ex":{"en":"...fragrant oils and perfumes","cn":"芳香精油和香水"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to have a pleasant smell","cn":""},{"en":"having a light, pleasant smell, especially of flowers","cn":""},{"en":"having a clean, natural, pleasant smell","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is fragrant has a nice smell. What makes a smell nice is subjective, or course. You might find bowl of dried lavender to be fragrant , but your dog might prefer a pile of horse poop."}]},"collocations":{"phrases":["VERBS be, smell | become","ADV. extremely, very, wonderfully a garden full of wonderfully fragrant flowers | mildly, slightly, subtly","PREP. with The air was fragrant with lavender."]},"media":{"uk":"media/ldoce/hwd/bre/e/fragrant0205.mp3","us":"media/ldoce/hwd/ame/6/fragrant.mp3"},"examples":[{"en":"The air was fragrant with scents from the sea and the hills.","cn":"空气中荡漾着山和海的芬芳气息。"},{"en":"fragrant herbs/flowers/oils","cn":"芳草；香花/油"}],"oxford":{"phon":"ˈfreɪɡrənt","pos":"adjective","senses":[{"en":"having a pleasant smell","cn":"香的；芳香的","ex":{"en":"fragrant herbs/flowers/oils","cn":"芳草；香花；精油"}}]}},"fright":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指令人不快的事意外发生造成的)惊骇，恐惧","en":"Fright is a sudden feeling of fear, especially the fear that you feel when something unpleasant surprises you.","ex":{"en":"The steam pipes rattled suddenly, and Franklin uttered a shriek and jumped with fright","cn":"蒸汽管突然发出咯咯的响声，富兰克林尖叫一声，吓得跳了起来。"}},{"pos":"N-COUNT 可数名词","cn":"惊吓;恐怖的体验","en":"A fright is an experience which makes you suddenly afraid.","ex":{"en":"The snake picked up its head and stuck out its tongue which gave everyone a fright","cn":"蛇突然昂起头，吐出芯子，每个人都吓了一跳。"}},{"pos":"PHRASE 短语","cn":"(因…)受惊吓","en":"If a person or animal takes fright at something, they are suddenly frightened by it, and want to run away or to stop doing what they are doing.","ex":{"en":"An untrained horse had taken fright at the sound of gunfire","cn":"一匹未经训练的马听到枪响受了惊。"}},{"pos":"","cn":"","en":"the fright of your life→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of being frightened","cn":""},{"en":"a feeling of great fear, because you think that something terrible is about to happen","cn":""},{"en":"a sudden feeling of fear, or a situation that makes you feel this","cn":""}]},"collocations":{"phrases":["VERB + FRIGHT take | be shaking/trembling with | die of (informal) He almost died of fright when the fish jumped out of the water.","PREP. in ~ She cried out in fright. | with ~ They were paralysed with fright. | ~ at The birds took fright at the sight of the cat and flew ","ADJ. awful, bad, dreadful, nasty, terrible","VERB + FRIGHT get, have Emma got such a fright that she dropped the tray. I had a terrible fright this morning when I saw you there. | give ","PHRASES a bit of a fright, the fright of your life You gave me the fright of my life, jumping out like that! | quite a fright"]},"media":{"uk":"media/ldoce/hwd/bre/2/fright0205.mp3","us":"media/ldoce/hwd/ame/3/fright.mp3"},"examples":[{"en":"You gave me a fright jumping out at me like that.","cn":"你这样跳起来扑向我，把我吓了一大跳。"},{"en":"The birds took fright and flew off.","cn":"鸟受惊飞走了。"}],"oxford":{"phon":"fraɪt","pos":"noun","senses":[{"en":"a feeling of fear","cn":"惊吓；恐怖","g":"[uncountable]","ex":{"en":"She cried out in fright.","cn":"她吓得大声叫喊。"}},{"en":"an experience that makes you feel fear","cn":"使人惊吓的经历；恐怖的经历","g":"[countable]","ex":{"en":"You gave me a fright jumping out at me like that.","cn":"一眼看到你，把我吓了一大跳。"}}]}},"france":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in western Europe and a member of the EU. Population: 65,951,611 (2014). Capital: Paris. France is known especially for its art, good food, and fine wines, and many British people go there on holiday. People from France are called French.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000005079.mp3","us":"media/ldoce/hwd/ame/7/p028-000005079.mp3"},"oxford":{"phon":"frɑːns","pos":"noun","senses":[{"en":"a country in western Europe","cn":"法国（西欧国家）"}]}},"fracture":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"破裂;(尤指)骨折","en":"A fracture is a slight crack or break in something, especially a bone.","ex":{"en":"At least one-third of all women over ninety have sustained a hip fracture.","cn":"超过90岁的所有女性中至少有1/3已经出现髋骨骨折。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(轻微)骨折;(使)断裂","en":"If something such as a bone is fractured or fractures, it gets a slight crack or break in it.","ex":{"en":"You've fractured a rib, maybe more than one","cn":"你的一根肋骨断了，可能不止一根。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)分裂;(使)解散","en":"If something such as an organization or society is fractured or fractures, it splits into several parts or stops existing.","ex":{"en":"His policy risks fracturing the coalition","cn":"他的政策有分裂联盟的风险。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to damage something and make it separate into pieces, for example by dropping it or hitting it","cn":""},{"en":"to break something with a lot of force","cn":""},{"en":"to break something into two pieces, making a loud noise – used especially about long thin objects","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"Think of something hard breaking in a crisp, snapping manner, and you've just imagined a fracture . The word is most often applied to a broken bone, but it can used to describe any sharp, sudden break of something solid."}]},"collocations":{"phrases":["ADJ. fatigue, stress He suffered a stress fracture of the right foot. | hairline | compound, depressed, double, multiple, simple, spiral | h","VERB + FRACTURE suffer, sustain"]},"media":{"uk":"media/ldoce/hwd/bre/1/fracture_n0205.mp3","us":"media/ldoce/hwd/ame/5/fracture1.mp3"},"examples":[{"en":"a compound/simple fracture (= one in which the broken bone comes/does not come through the skin)","cn":"复合（开放）骨折；单纯（闭合）骨折"},{"en":"The company was fractured into several smaller groups.","cn":"这家公司被支解成几家小公司。"}],"oxford":{"phon":"ˈfræktʃə(r)","pos":"noun","senses":[{"en":"a break in a bone or other hard material","cn":"（指状态）骨折，断裂，折断，破裂","g":"[countable]","lab":"especially British English","ex":{"en":"a fracture of the leg/skull","cn":"腿骨／颅骨骨折"}},{"en":"the fact of something breaking, especially a bone","cn":"（指事实）骨折，断裂，折断，破裂","g":"[uncountable]","ex":{"en":"Old people's bones are more prone to fracture.","cn":"老人更易骨折。"}},{"en":"to break or crack; to make something break or crack","cn":"（使）断裂，折断，破裂","g":"[intransitive, transitive]","ex":{"en":"His leg fractured in two places.","cn":"他的一条腿有两处骨折。"},"pos":"verb"},{"en":"to split into several parts so that it no longer functions or exists; to split a society or an organization, etc. in this way","cn":"（使）分裂","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"Many people predicted that the party would fracture and split.","cn":"很多人预言该党将分崩离析。"},"pos":"verb"}]}},"froth":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(液体表面的)泡,泡沫","en":"Froth is a mass of small bubbles on the surface of a liquid.","ex":{"en":"...the froth of bubbles on the top of a glass of beer","cn":"一杯啤酒表面的啤酒沫"}},{"pos":"VERB 动词","cn":"起泡沫;生泡沫","en":"If a liquid froths, small bubbles appear on its surface.","ex":{"en":"The sea froths over my feet","cn":"海水在我的脚上泛起泡沫。"}},{"pos":"VERB 动词","cn":"(因非常愤怒或激动而)嘴喷唾沫，口吐白沫","en":"If you say that someone is frothing, or that they are frothing at the mouth, you are emphasizing that they are very angry or excited about something.","ex":{"en":"'No! No! Never!' he froths","cn":"“不！不！绝不!”他气得口吐白沫。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"迷人但没有实际价值的事物;虚浮的东西","en":"If you refer to an activity or object as froth, you disapprove of it because it appears exciting or attractive, but has very little real value or importance.","ex":{"en":"No substance at all, just froth","cn":"根本没有任何实质，只是一些虚浮的东西。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mass of small bubble s on the top of a liquid 〔","cn":"液体表面的〕泡沫"},{"en":"small white bubble s of saliva around a person’s or animal’s mouth 〔","cn":"人或动物嘴里流出的〕白沫"},{"en":"talk or ideas that are attractive but have no real value or meaning 〔","cn":"吸引人的〕空谈﹐空想"}]},"vocab":{"pos":"n v","senses":[{"en":"Froth is the gathering of small bubbles at the top of a drink, like the fizzy froth on the top of your root beer float."}]},"media":{"uk":"media/ldoce/hwd/bre/5/froth_las3_br.mp3","us":"media/ldoce/hwd/ame/1/froth1.mp3","img":["media/pic/froth_comp.jpg","media/thumb/froth.jpg"]},"examples":[{"en":"a glass of beer with thick froth on top","cn":"上面有厚厚一层泡沫的一杯啤酒"},{"en":"( figurative ) He frothed at the mouth (= was very angry) when I asked for more money.","cn":"我还要钱时他气得七窍生烟。"}],"oxford":{"phon":"frɒθ","pos":"noun","senses":[{"en":"a mass of small bubbles, especially on the surface of a liquid","cn":"（尤指液体表面的）泡沫，泡","g":"[uncountable]","ex":{"en":"a glass of beer with thick froth on top","cn":"上面有厚厚一层泡沫的一杯啤酒"}},{"en":"ideas, activities, etc. that seem attractive and fun but have no real value","cn":"华而不实的想法（或活动等）","g":"[uncountable]"},{"en":"something that looks like a mass of small bubbles on liquid","cn":"泡沫状物","g":"[singular]","ex":{"en":"a froth of black lace","cn":"气泡状的黑色花边"}},{"en":"if a liquid froths, or if somebody/something froths it, a mass of small bubbles appears on the surface","cn":"（使）起泡沫","g":"[intransitive, transitive]","ex":{"en":"a cup of frothing coffee","cn":"一杯起泡的咖啡"},"pos":"verb"},{"en":"to produce a lot of saliva (= liquid in your mouth)","cn":"（口）吐白沫","g":"[intransitive]","lab":"figurative","ex":{"en":"The dog was frothing at the mouth.","cn":"这条狗口吐白沫。"},"pos":"verb"}]}}});
